function archiveText(value){let text=String(value);for(const [before,after] of archivePhrases)text=text.replaceAll(before,after);return projectText(text);}
function runwayText(c){if(c.liquidation)return '已停业 · 以下是最后一期账';if(c.pendingDivestPrice)return '本年已有出售 · 收入成本待下份年报更新';return c.cashFlow>0?'经营有现金结余':c.cashFlow===0?'现金收支平衡':c.runway+' 个月现金储备';}
function financeSummary(c){return `<div class="operating-metrics"><div><label>年收入 / 万</label><b>${num(c.revenue)}</b></div><div><label>总成本 / 万</label><b>${num(c.costs)}</b></div><div><label>税前利润 / 万</label><b class="${c.profit>=0?'positive':'negative'}">${signed(c.profit)}</b></div><div><label>企业现金 / 万</label><b>${num(c.cash)}</b></div></div><div class="finance-caption">同行竞争 ${pct(c.competition)} · 利润率 ${pct(c.profit/Math.max(1,c.revenue))} · ${runwayText(c)}${VC.debtBalance(c)>0?` · 未偿贷款 ${num(VC.debtBalance(c))} 万 · 下期本息 ${num(VC.debtService(c))} 万`:""}</div>`;}
function cashLedger(r){
 if(r.opening)return '<p class="modal-note">这是投资前的账，股东后来投入的资金另记。</p>';
 const financing=(r.financing||0)+(r.loanDrawdown||0)+(r.acquisitionEquity||0)+(r.rescueEquity||0);
 return `<details class="transaction-rules"><summary>核对这一年的现金</summary><div class="cost-breakdown"><span>期初现金 <b>${num(r.cashOpening)} 万</b></span><span>经营后现金流 <b>${signed(r.cashFlow)} 万</b></span><span>融资、借款与增资到账 <b>${num(financing)} 万</b></span><span>出售收款 <b>${num(r.divestPrice||0)} 万</b></span><span>收购价款 <b>${num(r.acquisitionPaid||0)} 万</b></span><span>偿还本金 <b>${num(r.principalPaid||0)} 万</b></span><span>所有股东分红 <b>${num(r.dividend||0)} 万</b></span><span>期末现金 <b>${num(r.cash)} 万</b></span></div><p class="modal-note">研发、招聘和交易费用已在成本里；买设备记在资本开支。还本金和分红从现金付，不算经营成本。展期、转股等没有付现金的费用，会从现金流里加回来。</p></details>`;
}
function fullFinanceDetails(c){const rows=c.financialHistory;const r=rows.at(-1);return `${dividendHistory(c)}${liquidationHistory(c)}${divestHistory(c)}${rebuildHistory(c)}${financeSummary(c)}${workoutHistory(c)}${financingHistory(c)}${acquisitionHistory(c)}${companyMarket(c)}${c.pendingAcquisitionPrice||c.pendingWorkoutFee||c.pendingDivestPrice||c.pendingRebuildExpense||c.pendingRebuildCapex||c.pendingDividend||c.pendingAllocationPrincipal?'<p class="modal-note">今年新办的交易在上面的档案里；年报还停在上次结账时，下年会把这些钱的来去列进去。</p>':''}<h4>这笔成本花在了哪里 / 万元</h4><div class="cost-breakdown"><span>产品与交付 <b>${num(r.variableCost)}</b></span><span>人员 <b>${num(r.payrollCost)}</b></span><span>营销获客 <b>${num(r.marketing)}</b></span><span>研发 <b>${num(r.rnd)}</b></span><span>固定费用 <b>${num(r.overhead)}</b></span><span>并购交易费用 <b>${num(r.acquisitionFee||0)}</b></span><span>整合费用 <b>${num(r.integrationCost||0)}</b></span><span>贷款利息 <b>${num(r.interestExpense||0)}</b></span><span>重组及救助费用 <b>${num(r.workoutFee||0)}</b></span><span>剥离出售费用 <b>${num(r.divestFee||0)}</b></span><span>再投资费用 <b>${num(r.rebuildExpense||0)}</b></span></div>${cashLedger(r)}<h4>历年账目</h4><p class="modal-note">${rows[0]?.event.includes('迁移')?'第一行是接续旧档时留下的期初账，以前的年份照原账保留。':'第一行是投资前的账。股东后来投进来的钱，另记在融资里。'} 账本较宽，左右滑动可看后面的栏。</p><div class="financial-table" tabindex="0" role="region" aria-label="年度财务明细"><table><thead><tr><th>年份</th><th>客户</th><th>份额</th><th>收入</th><th>成本</th><th>利润</th><th>净现金流</th><th>股东分红</th><th>提前还本</th><th>再投资费用</th><th>产能建设</th><th>出售回款</th><th>出售费用</th><th>基金救助</th><th>重组费用</th><th>非现金费用</th><th>债转股</th><th>其他增资</th><th>并购增资</th><th>贷款提款</th><th>利息</th><th>应还本金</th><th>实还本金</th><th>剩余贷款</th><th>收购价款</th><th>交易费</th><th>整合费</th><th>期末现金</th><th>竞争</th><th>投后支持</th></tr></thead><tbody>${[...rows].reverse().map(x=>`<tr><td>${x.year}${x.opening?' 期初':''}</td><td>${x.market?whole(x.market.customers):'—'}</td><td>${x.market?pct(x.market.share):'—'}</td><td>${num(x.revenue)}</td><td>${num(x.costs)}</td><td class="${x.profit>=0?'positive':'negative'}">${signed(x.profit)}</td><td>${signed(x.cashFlow)}</td><td>${num(x.dividend||0)}</td><td>${num(x.allocationPrincipal||0)}</td><td>${num(x.rebuildExpense||0)}</td><td>${num(x.rebuildCapex||0)}</td><td>${num(x.divestPrice||0)}</td><td>${num(x.divestFee||0)}</td><td>${num(x.rescueEquity||0)}</td><td>${num(x.workoutFee||0)}</td><td>${num(x.noncashFee||0)}</td><td>${num(x.debtConversion||0)}</td><td>${num(x.financing)}</td><td>${num(x.acquisitionEquity||0)}</td><td>${num(x.loanDrawdown||0)}</td><td>${num(x.interestExpense||0)}</td><td>${num(x.principalDue||0)}</td><td>${num(x.principalPaid||0)}</td><td>${num(x.debtBalance||0)}</td><td>${num(x.acquisitionPaid||0)}</td><td>${num(x.acquisitionFee||0)}</td><td>${num(x.integrationCost||0)}</td><td>${num(x.cash)}</td><td>${pct(x.competition)}</td><td>${x.support?x.support+' 级':'—'}</td></tr>`).join('')}</tbody></table></div>`;}
let marketFilter='企业软件';
const whole=n=>Math.round(n).toLocaleString('zh-CN');
const shareDelta=n=>Math.abs(n)<.00005?'0.00':(n>0?'+':'')+(n*100).toFixed(2);
function companyMarket(c){const f=c.market;if(!f)return '<p class="modal-note">这笔投资结束得早，没有留下当年的同行资料。</p>';const m=state.markets[c.sector],rivals=f.rivals||m.members.filter(x=>x.id!==c.id&&!x.failed&&!x.acquiredBy).sort((a,b)=>b.customers-a.customers).slice(0,3).map(x=>({...x,share:x.customers/m.total}));const row=c.financialHistory.at(-1);return `<section class="competition-report" data-sector="${esc(c.sector)}"><div class="eyebrow">客户与同行 · ${f.year}</div><h4>${f.opening?'投资前的客户情况':'这一年，客户去了哪里'}</h4><div class="market-kpis"><div><label>折算客户</label><b>${whole(f.customers)}</b></div><div><label>市场份额</label><b>${pct(f.share)}</b></div><div><label>份额变化</label><b class="${f.delta>=0?'positive':'negative'}">${shareDelta(f.delta)}<small> 个百分点</small></b></div><div><label>户均年收入 / 万</label><b>${num(f.unitPrice)}</b></div></div><p class="modal-note">${f.opening?'这份客户数由期初收入折算，后续得看企业能留下多少老客户、接到多少新客户。':`赢得对手客户 ${whole(f.won)} · 流失至对手 ${whole(f.lost)} · 新需求及尚未落定的客户 ${whole(f.newDemand)} · 市场收缩损失 ${whole(f.contraction)}。收入 = ${whole(f.customers)} 折算客户 × ${f.unitPrice.toFixed(3)} 万（显示值四舍五入）。`}</p>${!f.opening?`<div class="customer-flows"><div><b>客户从哪里来</b>${f.from.length?f.from.map(x=>`<p>${esc(companyRef(x))} <span class="positive">+${whole(x.count)}</span></p>`).join(''):'<p>今年没有从同行手里接到新客户</p>'}</div><div><b>客户去了哪里</b>${f.to.length?f.to.map(x=>`<p>${esc(companyRef(x))} <span class="negative">−${whole(x.count)}</span></p>`).join(''):'<p>今年没有客户转去同行</p>'}</div></div>`:''}<h4>主要对手${f.opening?'':' · 年报时点'}</h4><div class="rival-list">${rivals.map(r=>`<div><span>${esc(companyRef(r))}<small>${VC.strategies[r.strategy].name}</small></span><b>${pct(r.share)}</b></div>`).join('')}</div>${!f.opening?`<details><summary>交易部的看法</summary><p class="modal-note">${Number.isFinite(row.exitChance)?'按今年的经营和市场，退出撮合机会约 '+pct(row.exitChance)+'。':''}份额在增长还是流失，会影响买方的兴趣。上市至少需要 2.5% 的行业份额，还得满足盈利、收入和持有年限等条件；有机会，不代表已经谈成。</p></details>`:''}</section>`;}
function marketPage(){const sectors=Object.keys(state.markets);if(!sectors.includes(marketFilter))marketFilter=sectors[0];const m=state.markets[marketFilter],rows=[...m.members].sort((a,b)=>a.failed-b.failed||b.customers-a.customers||a.id.localeCompare(b.id)),active=rows.filter(x=>!x.failed&&!x.acquiredBy),held=new Set(state.portfolio.filter(c=>c.status==='active').map(c=>c.id)),top=active.slice(0,4);return `<div class="section-intro"><span>几家企业，争的是同一批客户</span><select id="market-filter" aria-label="选择竞争行业">${sectors.map(k=>`<option ${k===marketFilter?'selected':''}>${esc(k)}</option>`).join('')}</select></div><section class="market-board" data-sector="${esc(marketFilter)}"><div class="eyebrow">行业快报 · ${state.year}</div><h2>${esc(m.sector)}市场</h2><div class="market-kpis"><div><label>市场客户总量</label><b>${whole(m.total)}</b></div><div><label>本年需求变化</label><b class="${m.growth>=0?'positive':'negative'}">${signed(m.growth*100)}<small>%</small></b></div><div><label>经营中企业</label><b>${active.length}</b></div><div><label>尚未落定的客户</label><b>${whole(m.unserved)}</b></div></div><div class="share-bar" role="img" aria-label="行业客户份额分布">${top.map((x,i)=>`<span style="width:${x.customers/m.total*100}%;background:${['#19374e','#486578','#8299a6','#b6c4ca'][i]}" title="${esc(companyRef(x))} ${pct(x.customers/m.total)}"></span>`).join('')}</div><div class="share-legend">${top.map(x=>`<span>${esc(companyRef(x))} <b>${pct(x.customers/m.total)}</b></span>`).join('')}<span>其他企业与待定客户 <b>${pct(1-top.reduce((n,x)=>n+x.customers,0)/m.total)}</b></span></div><p class="modal-note">同行争的是同一批客户，没投的项目和已经卖出的企业也还在做生意。这里的客户数按同一口径折算，不等于实际人数。客户列是眼下的份额，收入和利润来自最近一期年报。</p><div class="financial-table market-table" tabindex="0" role="region" aria-label="同行企业与市场份额"><table><thead><tr><th>企业</th><th>客户</th><th>份额</th><th>经营策略</th><th>户均年收入 / 万</th><th>最近收入 / 万</th><th>最近利润 / 万</th></tr></thead><tbody>${rows.map(x=>`<tr class="${held.has(x.id)?'held-company':''}"><td>${esc(companyName(x))}${projectTag(x)}<small>${x.acquiredBy?'已并入 '+esc(companyRef(m.members.find(y=>y.id===x.acquiredBy)||x.acquiredBy)):x.failed?'已停止经营':held.has(x.id)?'本基金持仓':'同行企业'}</small></td><td>${whole(x.customers)}</td><td>${pct(x.customers/m.total)}</td><td>${x.failed||x.acquiredBy?'—':VC.strategies[x.strategy].name}</td><td>${x.unitPrice.toFixed(2)}</td><td>${num(x.revenue)}</td><td class="${x.profit>=0?'positive':'negative'}">${signed(x.profit)}</td></tr>`).join('')}</tbody></table></div><p class="modal-note">上年有 ${whole(m.last?.transfers||0)} 个折算客户换了供应商。降价、营销、产品和交付，都会左右客户下一年找谁下单。</p></section>`;}




function allocationHint(c){const q=VC.dividendQuote(state,c.id);return q.ok?'本年可分红':VC.dividendQuote(state,c.id,0,1).ok?'可提前偿债 · 分红：'+esc(q.reason):esc(q.reason);}
function dividendHistory(c){if(!c.dividends?.length)return '';return `<section class="acquisition-history"><div class="eyebrow">分红记录</div><h4>历次分红与还债</h4><p>基金累计分红到账 <b>${num(c.dividendReceived)} 万</b>；不改变持股比例。</p>${[...c.dividends].reverse().map(a=>`<article class="acquisition-entry"><b>${a.year}${a.repaymentOnly?' · 只偿债':''} · 分红 ${pct(a.payout)} / 偿债 ${pct(a.repay)}</b><p class="modal-note">可安排资金 ${num(a.pool)} 万：所有股东分红 ${num(a.dividend)} 万，基金按 ${pct(a.equity)} 持股收到 ${num(a.fundProceeds)} 万，其他股东收到 ${num(a.otherProceeds)} 万；提前还本 ${num(a.principal)} 万，留存 ${num(a.retained)} 万。企业现金 ${num(a.cashBefore)} → ${num(a.cashAfter)} 万，贷款 ${num(a.debtBefore)} → ${num(a.debtAfter)} 万。</p></article>`).join('')}</section>`;}
function dividendDesk(id,payout=.5,repay=0){const c=state.portfolio.find(x=>x.id===id);if(!c)return;const q=VC.dividendQuote(state,id,payout,repay);modal(`<div class="eyebrow">董事会决议</div><h2>${esc(companyName(c))} · 今年的利润怎么安排</h2>${projectTag(c)}<p>先留够周转和还债的钱，剩下的利润再拿出来分。也可以先还贷款，或把钱留在公司。</p>${q.pool!==undefined?`<section class="financing-plan"><h4>${q.repaymentOnly?'只偿债 · 储备外现金':'可安排利润'} / 万元</h4><div class="cost-breakdown"><span>累计未分配经营利润 <b>${num(q.earnings)}</b></span><span>近两年较低净现金流 <b>${num(q.stableCash)}</b></span><span>留够半年开支（至少 30 万） <b>${num(q.operatingReserve)}</b></span><span>下期本息 / 项目备用金 <b>${num(q.service)} / ${num(q.contingency)}</b></span>${q.integrationReserve?`<span>留给并购整合的钱 <b>${num(q.integrationReserve)}</b></span>`:''}<span>留足储备后的现金 <b>${num(Math.max(0,c.cash-q.reserve))}</b></span><span>这次最多能动用 <b>${num(q.pool)}</b></span></div></section><h4>拿多少分红</h4><div class="financing-options" role="group" aria-label="拿多少分红">${VC.allocationRates.map(rate=>`<button data-payout="${rate}" class="${rate===payout?'primary':''}" aria-pressed="${rate===payout}">${pct(rate)}</button>`).join('')}</div><h4>拿多少还债</h4><div class="financing-options" role="group" aria-label="拿多少还债">${VC.allocationRates.map(rate=>`<button data-profit-repay="${rate}" class="${rate===repay?'primary':''}" aria-pressed="${rate===repay}" ${rate>0&&q.debtBefore<=0?'disabled':''}>${pct(rate)}</button>`).join('')}</div><section class="financing-plan"><h4>这笔钱怎么分 / 万元</h4><div class="cost-breakdown"><span>所有股东分红 <b>${num(q.dividend)}</b></span><span>基金到账 · 持股 ${pct(q.equity)} <b class="positive">+${num(q.fundProceeds)}</b></span><span>其他股东到账 <b>${num(q.otherProceeds)}</b></span><span>提前还本（高息优先） <b>${num(q.principal)}</b></span><span>仍留在公司 <b>${num(q.retained)}</b></span><span>企业现金 <b>${num(q.cashBefore)} → ${num(q.cashAfter)}</b></span><span>未偿贷款 <b>${num(q.debtBefore)} → ${num(q.debtAfter)}</b></span></div></section>`:''}<details class="transaction-rules"><summary>财务核对的分红条件</summary><p class="modal-note">分红要用已经赚到、也确实留在账上的钱。过去的亏损先补回来，最近两个完整年度的利润和现金流还得都为正。融资、并购、重组、救助、出售当年和整合期间，先不分红。只还本金不受这些分红条件限制，但经营、本息和未完项目的钱都得留够。</p></details><p class="modal-note">今年只能确认一次。分红和还债合计不超过 100%，调高一项会相应调低另一项；超过剩余贷款的偿债金额，仍留在公司。</p><p class="modal-note">${q.repaymentOnly?'这笔钱直接付给债权人，基金不收分红。以后按还款后的本金付息。':'公司向所有股东付款，基金按持股比例收钱。分出去的现金也会从股权估值里扣下，持股不变。'}留下的钱仍在公司账上，之后再决定怎么花。</p>${q.reason?`<div class="round-note">${esc(q.reason)}</div>`:''}<div class="modal-actions"><button id="cancel-dividend">回到投资组合</button><button id="confirm-dividend" class="primary" ${q.ok?'':'disabled'}>${q.repaymentOnly?'确认提前偿债':payout===0&&repay===0?'今年全部留在公司':'就按这个方案分'}</button></div>${dividendHistory(c)}`);
 document.querySelectorAll('[data-payout]').forEach(b=>b.onclick=()=>{const rate=Number(b.dataset.payout);dividendDesk(id,rate,Math.min(repay,1-rate));});document.querySelectorAll('[data-profit-repay]').forEach(b=>b.onclick=()=>{const rate=Number(b.dataset.profitRepay);dividendDesk(id,Math.min(payout,1-rate),rate);});$('cancel-dividend').onclick=close;$('confirm-dividend').onclick=()=>{if(VC.distribute(state,id,payout,repay)){render();modal(`<div class="eyebrow">资金已安排</div><h2>今年的钱安排好了</h2>${projectTag(c)}${dividendHistory(c)}<div class="modal-actions"><button id="dividend-done">回到投资组合</button></div>`);$('dividend-done').onclick=close;toast(q.repaymentOnly?`已提前偿还贷款 ${num(q.principal)} 万元。`:`基金分红到账 ${num(q.fundProceeds)} 万元。`);}else dividendDesk(id,payout,repay);};}

function rebuildHistory(c){if(!c.rebuilds?.length)return '';return `<section class="acquisition-history"><div class="eyebrow">建设记录</div><h4>建设项目档案</h4><div class="operating-metrics"><div><label>产能 / 起步时规模</label><b>${pct(VC.effectiveCapacity(c))}</b></div><div><label>技术积累</label><b>${pct(c.technologyBonus)}</b></div><div><label>渠道积累</label><b>${pct(c.marketReach)}</b></div><div><label>已建成设备的原值 / 万</label><b>${num(c.rebuiltCapital)}</b></div></div>${c.rebuilds.map(p=>`<article class="acquisition-entry"><b>${p.year} · ${VC.rebuildTypes[p.type]} · ${p.status}</b><p class="modal-note">已完成 ${p.stage}/2 阶段 · 已用 ${p.attempts}/3 年 · 预算 ${num(p.budget)} 万 · 累计投入 ${num(p.spent)} 万${p.endYear?' · '+p.endYear+' 年结束':''}。${p.events.length?'':'资金已支付，下一年度开始结算进展。'}</p>${p.events.map(e=>`<p class="modal-note">${e.year} · ${esc(archiveText(e.reason))} · 超支 ${num(e.extra)} 万 · 能力增加 ${(e.gain*100).toFixed(1)} 个百分点${e.employees?' · 招聘 '+e.employees+' 人':''} · 当年预计执行风险 ${pct(e.risk)}</p>`).join('')}</article>`).join('')}<p class="modal-note">卖掉的客户不会因为添设备自动回来，还得再去争取。设备只按已经建成的部分估值，未完工的预算不能当成现成资产卖。</p></section>`;}
function rebuildProgress(id){const c=state.portfolio.find(x=>x.id===id),p=c&&VC.currentRebuild(c);if(!p)return;modal(`<div class="eyebrow">项目进展</div><h2>${esc(companyName(c))} · ${VC.rebuildTypes[p.type]}</h2>${projectTag(c)}<p>项目已经开工，${num(p.budget)} 万预算也已付出。公司账上还剩 ${num(c.cash)} 万，下一份进展在来年的报告里；原预算不再付第二次。</p>${rebuildHistory(c)}<div class="modal-actions"><button id="close-rebuild-progress">回到投资组合</button><button id="stop-rebuild-progress">停下这个项目</button></div>`);$('close-rebuild-progress').onclick=close;$('stop-rebuild-progress').onclick=()=>{modal(`<h2>终止${VC.rebuildTypes[p.type]}？</h2><p>已花的 ${num(p.spent)} 万不会退回，已经做出的成果保留。今年也不能再开第二个项目。</p><div class="modal-actions"><button id="keep-rebuild-progress">继续做下去</button><button id="confirm-stop-progress">确认停项</button></div>`);$('keep-rebuild-progress').onclick=()=>rebuildProgress(id);$('confirm-stop-progress').onclick=()=>{if(VC.cancelRebuild(state,id)){render();rebuildDesk(id);}};};}
function rebuildDesk(id,type='capacity',budget=50){const c=state.portfolio.find(x=>x.id===id);if(!c)return;if(VC.currentRebuild(c))return rebuildProgress(id);const q=VC.rebuildQuote(state,id,type,budget),p=VC.currentRebuild(c);modal(`<div class="eyebrow">项目送审</div><h2>${esc(companyName(c))} · 再投资与业务重建</h2>${projectTag(c)}<p>这笔预算由公司出，签字后立即付款。计划分两阶段，顺利的话两年做完；遇到困难可能拖到第三年，届时还没完成就停项。基金不用另掏钱，持股也不变。</p><div class="financing-options" role="group" aria-label="重建方向">${Object.entries(VC.rebuildTypes).map(([k,v])=>`<button data-rebuild-type="${k}" class="${k===type?'primary':''}" aria-pressed="${k===type}">${v}</button>`).join('')}</div><h4>这次准备投多少</h4><div class="financing-options" role="group" aria-label="重建预算">${VC.rebuildBudgets(state,c).map(b=>`<button data-rebuild-budget="${b}" class="${b===budget?'primary':''}" aria-pressed="${b===budget}">${b} 万</button>`).join('')}</div>${q.budget!==undefined?`<section class="financing-plan"><h4>预算送审</h4><div class="cost-breakdown"><span>企业现金 <b>${num(q.cashBefore)} → ${num(q.cashAfter)} 万</b></span><span>留下周转和还债的钱 <b>${num(q.reserve)} 万</b></span><span>另留项目备用金 <b>${num(q.contingency)} 万</b></span>${q.protectDividend?'<span>同年已分红 <b>继续保留半年经营储备</b></span>':''}<span>有投后经理跟进后的执行风险 <b>${pct(q.risk)} / 年</b></span><span>两阶段预计提升 <b>${(q.gain*100).toFixed(1)} 个百分点</b></span><span>最快完工 / 最迟停项 <b>${state.year+2} / ${Math.min(state.year+3,VC.endYear(state))}</b></span></div></section>`:''}<p class="modal-note">${type==='capacity'?'设备款记在资本开支里。建成后可以缓解交付压力，产能最高到起步时的 125%；设备每年折旧 15%，另有约原值 2% 的维护费。':type==='rnd'?'研发费会进入下一期成本。做成的部分能改善产品和交付，技术积累最高增加 15%；客户是否买单，还要去市场上争。':'渠道费会进入下一期成本，新招的人以后还要继续付工资。渠道积累最多增加 40%，每年衰减 8%；争到更多客户，也需要更多周转钱。'}</p><div class="round-note">最近一年现金流转正、没有逾期，才能开新项目；出售或救助当年先经营一年。${VC.endYear(state)-1} 年起不再立项。每家同时做一个，每年只能开一次。延期时可能追加预算的 10%；钱不够就继续等，不强扣。停项不退款，已经做出的成果保留。</div>${q.reason?`<p class="danger">${esc(q.reason)}</p>`:''}<div class="modal-actions"><button id="cancel-rebuild-desk">回到投资组合</button>${p?'<button id="stop-rebuild">停下这个项目</button>':''}<button id="confirm-rebuild" class="primary" ${q.ok?'':'disabled'}>确认投入 · ${budget} 万</button></div>${rebuildHistory(c)}`);document.querySelectorAll('[data-rebuild-type]').forEach(b=>b.onclick=()=>rebuildDesk(id,b.dataset.rebuildType,budget));document.querySelectorAll('[data-rebuild-budget]').forEach(b=>b.onclick=()=>rebuildDesk(id,type,Number(b.dataset.rebuildBudget)));$('cancel-rebuild-desk').onclick=close;$('confirm-rebuild').onclick=()=>{if(VC.reinvest(state,id,type,budget)){render();rebuildDesk(id,type,budget);toast('预算已付，来年等企业报进展。');}};if($('stop-rebuild'))$('stop-rebuild').onclick=()=>{modal(`<h2>终止${VC.rebuildTypes[p.type]}？</h2><p>已花的 ${num(p.spent)} 万不会退回，已经做出的成果保留。停项后可再谈出售，但今年不能再开第二个项目。</p><div class="modal-actions"><button id="keep-rebuild">继续做下去</button><button id="confirm-stop-rebuild">确认停项</button></div>`);$('keep-rebuild').onclick=()=>rebuildDesk(id,type,budget);$('confirm-stop-rebuild').onclick=()=>{if(VC.cancelRebuild(state,id)){render();rebuildDesk(id,type,budget);}};};}

const divestNames={assets:'部分资产出售',business:'非核心业务剥离'};
function divestHistory(c){if(!c.divestments?.length)return '';return `<section class="acquisition-history"><div class="eyebrow">出售记录</div><h4>卖出过的业务和资产</h4><p class="modal-note">原有资产保留 ${pct(c.assetRetention)} · 原有业务保留 ${pct(c.businessRetention)}。出售款属于企业现金，不是基金退出回款。</p>${c.divestments.map(a=>`<article class="acquisition-entry"><b>${a.year} · ${divestNames[a.mode]} ${pct(a.fraction)}${a.buyerName?' → '+esc(companyRef({id:a.buyerId,name:a.buyerName})):''}</b><div class="cost-breakdown"><span>成交 / 费用 <b>${num(a.price)} / ${num(a.fee)} 万</b></span><span>本金偿还 <b>${num(a.principal)} 万</b></span><span>企业现金 <b>${num(a.cashBefore)} → ${num(a.cashAfter)}</b></span><span>未偿本金 <b>${num(a.debtBefore)} → ${num(a.debtAfter)}</b></span></div><p class="modal-note">转出 ${whole(a.customers)} 客户，买方接收 ${whole(a.transferred)}，释放 ${whole(a.released)}；转移 ${whole(a.employees)} 名员工。年收入基数减少 ${num(a.revenueSold)} 万；相同价格与客户留存下，预计经营成本 ${num(a.costBefore)} → ${num(a.costAfter)} 万。实际结果取决于后续竞争与策略。${a.resolves?'成交时现金与逾期缺口已消除。':'成交时仍有危机缺口，需继续救助。'}</p></article>`).join('')}</section>`;}
function divestDesk(id,mode='assets',fraction=.2,buyerId=null,repay=true){
 const c=state.portfolio.find(x=>x.id===id);if(!c)return;const buyers=VC.divestBuyers(state,id,fraction,repay);if(mode==='business'&&!buyerId)buyerId=(buyers.find(x=>x.ok)||buyers[0])?.id||null;const q=VC.divestQuote(state,id,mode,fraction,buyerId,repay);
 modal(`<div class="eyebrow">业务调整</div><h2>${esc(companyName(c))} · 卖出一部分业务或资产</h2>${projectTag(c)}<p>把一部分业务或资产交出去，公司继续做剩下的生意。卖价留在公司，先补缺口、还债或周转，基金这次不直接收钱，持股也不变。</p><div class="financing-options" role="group" aria-label="部分出售方式">${Object.entries(divestNames).map(([k,v])=>`<button data-divest-mode="${k}" aria-pressed="${mode===k}" class="${mode===k?'primary':''}">${v}</button>`).join('')}</div><h4>出售当前${mode==='business'?'业务':'资产'}比例</h4><div class="financing-options" role="group" aria-label="出售比例">${[.1,.2,.3].map(f=>`<button data-divest-fraction="${f}" aria-pressed="${f===fraction}" class="${f===fraction?'primary':''}">${pct(f)}</button>`).join('')}</div>${mode==='business'?`<h4>愿意接手的同行</h4><div class="liquidation-buyers">${buyers.map(b=>`<button data-divest-buyer="${esc(b.id)}" aria-pressed="${buyerId===b.id}" class="${buyerId===b.id?'selected':''}"><b>${esc(companyName(b))}</b>${projectTag(b)}<span>报价 ${num(b.price)} 万 · ${b.ok?'可成交':esc(b.reason)}</span></button>`).join('')||'<p>目前还没有同行愿意接这块业务。</p>'}</div>`:''}<h4>资金安排</h4><div class="financing-options" role="group" aria-label="出售资金用途"><button data-divest-repay="yes" class="${repay?'primary':''}" aria-pressed="${repay}">偿债 · 保留 20 万现金</button><button data-divest-repay="no" class="${repay?'':'primary'}" aria-pressed="${!repay}">保留经营现金</button></div><p class="modal-note">不管怎么安排，都先补现金缺口、还逾期本金。选优先偿债时，余款尽量留下 20 万周转，再从利息最高的贷款还起；卖价不够时，20 万也未必留得住。</p>${q.price!==undefined?`<section class="financing-plan"><h4>成交后的账 / 万元</h4><div class="cost-breakdown"><span>出售回款 / 费用 <b>${num(q.price)} / ${num(q.fee)}</b></span><span>扣费后到账 <b>${num(q.net)}</b></span><span>偿还本金（含逾期 ${num(q.mandatory)}） <b>${num(q.principal)}</b></span><span>企业现金 <b>${num(q.cashBefore)} → ${num(q.cashAfter)}</b></span><span>未偿本金 <b>${num(q.debtBefore)} → ${num(q.debtAfter)}</b></span><span>年收入基数 <b>${num(c.revenue)} → ${num(q.revenueAfter)}</b></span><span>经营成本估算 <b>${num(q.costBefore)} → ${num(q.costAfter)}</b></span><span>转出客户 / 员工 <b>${whole(q.customers)} / ${whole(q.employees)}</b></span><span>原有资产保留 <b>${pct(q.assetBefore)} → ${pct(q.assetAfter)}</b></span><span>原有业务保留 <b>${pct(q.businessBefore)} → ${pct(q.businessAfter)}</b></span></div></section><p class="modal-note">${mode==='assets'?'资产按设备、存货和技术的折价价值出售，费用 6%、最低 0.5 万、不超过售价。客户和员工暂时不走，但每卖掉原资产能力的 10%，获客实力少 5%，流失率多 0.8 个百分点，交付成本率多 0.6 个百分点，固定维护费少 1.5%。普通设备开支不会补回已经出售的额度。':'业务按经营价值与买方条件议价，费用 4%、最低 0.5 万、不超过售价。卖出部分的客户离开，90% 转给买方，余下的重新找供应商；员工随业务转移，公司至少留 3 人。部分固定开支会减少，产品积累也会损失，原债务仍由公司承担。'}价款进现金，交易费进下一期成本；表里的成本按眼下条件估算，尚未计未来利息和一次性费用。</p><div class="round-note">${q.resolves?'按这个价格成交，眼前的现金和逾期缺口能补上。':'按这个价格成交，缺口还是补不上，还得另想办法。'}每年最多卖一次，原资产能力至少留 60%、原业务至少留一半。今年旧跟投随之结束，也暂停股权转让和新并购。</div>`:''}${q.reason?`<p class="danger">${esc(q.reason)}</p>`:''}<div class="modal-actions"><button id="cancel-divest">继续评估</button><button id="confirm-divest" class="primary" ${q.ok?'':'disabled'}>按这个方案出售</button></div>`);
 document.querySelectorAll('[data-divest-mode]').forEach(b=>b.onclick=()=>divestDesk(id,b.dataset.divestMode,fraction,null,repay));document.querySelectorAll('[data-divest-fraction]').forEach(b=>b.onclick=()=>divestDesk(id,mode,Number(b.dataset.divestFraction),buyerId,repay));document.querySelectorAll('[data-divest-buyer]').forEach(b=>b.onclick=()=>divestDesk(id,mode,fraction,b.dataset.divestBuyer,repay));document.querySelectorAll('[data-divest-repay]').forEach(b=>b.onclick=()=>divestDesk(id,mode,fraction,buyerId,b.dataset.divestRepay==='yes'));$('cancel-divest').onclick=close;$('confirm-divest').onclick=()=>{if(VC.divest(state,id,mode,fraction,buyerId,repay)){render();modal(`<div class="eyebrow">企业继续经营</div><h2>${esc(companyName(c))} · 出售完成，继续经营</h2>${projectTag(c)}${divestHistory(c)}`);toast('出售完成，企业现金、债务与经营能力已更新。');}else divestDesk(id,mode,fraction,buyerId,repay);};
}

const liquidationNames={assets:'资产拍卖',business:'整门生意出售'};
function liquidationWaterfall(q){return `<section class="liquidation-waterfall"><h4>这次清算，钱怎么分 / 万元</h4><div><span>账上现金 + 出售价款</span><b>${num(q.cashAvailable)} + ${num(q.price)} = ${num(q.grossPool)}</b></div><div><span>01 · 优先支付处置费用</span><b>− ${num(q.fees)}</b></div><div><span>02 · 债权人受偿</span><b>− ${num(q.creditorPaid)}</b></div><div><span>还欠债权人的钱</span><b class="danger">${num(q.unpaid)}</b></div><div><span>03 · 留给全体股东</span><b>${num(q.equityResidual)}</b></div><div class="fund-recovery"><span>本基金回款 · 持股 ${pct(q.equity)}</span><b>${num(q.fundProceeds)}</b></div><div><span>其他股东回款</span><b>${num(q.otherEquity)}</b></div></section><p class="modal-note">待偿债务共 ${num(q.claims)} 万，其中贷款本金 ${num(q.loanClaims)} 万、经营欠款 ${num(q.operatingClaims)} 万。两类债权按同样顺位、同比例受偿。${q.unpaid>0?'还缺 '+num(q.unpaid)+' 万没还，股东这次拿不到钱。':'债务结清后，余款才按持股比例分给股东。'}</p>`;}
function liquidationHistory(c){const a=c.liquidation;if(!a)return '';return `<section class="acquisition-history"><div class="eyebrow">清算账目 · ${a.year}</div><h4>破产清算已完成 · ${liquidationNames[a.mode]}</h4><p class="modal-note">${a.automatic?'企业已经撑不下去，资产转入拍卖。':'基金已签字同意处置。'}${a.buyerName?'业务买方：'+esc(companyRef({id:a.buyerId,name:a.buyerName}))+'。':''} 企业已经停止独立经营，不能再卖一次或继续救助。历年账目原样归档，下面是停业时分给各方的钱。</p>${liquidationWaterfall(a)}<div class="financial-table" tabindex="0" role="region" aria-label="清算债权明细"><table><thead><tr><th>债权</th><th>申报金额</th><th>实际获偿</th><th>未获偿损失</th></tr></thead><tbody>${a.creditors.map(x=>`<tr><td>${esc(projectText(x.name))}</td><td>${num(x.claim)}</td><td>${num(x.paid)}</td><td>${num(x.unpaid)}</td></tr>`).join('')||'<tr><td colspan="4">没有未偿债务，扣费后余款归股东</td></tr>'}</tbody></table></div><p class="modal-note">原客户 ${whole(a.customers)} · 转入买方 ${whole(a.transferred)} · 释放至行业待匹配池 ${whole(a.released)}。${a.mode==='business'?'全部 '+whole(a.employees)+' 名员工随业务转移，后续收入和薪酬由买方承担。':'业务终止，下一年由同行重新争夺客户。'}</p></section>`;}
function liquidationDesk(id,mode='assets',buyerId=null){
 const c=state.portfolio.find(x=>x.id===id);if(!c)return;const buyers=VC.liquidationBuyers(state,id);if(mode==='business'&&!buyerId)buyerId=(buyers.find(x=>x.ok)||buyers[0])?.id||null;const q=VC.liquidationQuote(state,id,mode,buyerId);
 modal(`<div class="eyebrow">清算方案</div><h2>${esc(companyName(c))} · 资产出售与清算</h2>${projectTag(c)}<p>这份方案一签，公司就停止独立经营。卖价先付处置费，再还债，最后才轮到股东；此后不能再救助，也不再分享这门生意的未来。</p><div class="financing-options" role="group" aria-label="清算方式">${Object.entries(liquidationNames).map(([key,label])=>`<button data-liquidation-mode="${key}" aria-pressed="${mode===key}" class="${mode===key?'primary':''}">${label}</button>`).join('')}</div>${mode==='business'?`<h4>愿意全款接手的同行</h4><div class="liquidation-buyers">${buyers.map(b=>`<button data-liquidation-buyer="${esc(b.id)}" aria-pressed="${buyerId===b.id}" class="${buyerId===b.id?'selected':''}"><b>${esc(companyName(b))}</b>${projectTag(b)}<span>报价 ${num(b.price)} 万 · ${b.ok?'可成交':esc(b.reason)}</span></button>`).join('')||'<p class="modal-note">暂无独立同业买方，可返回资产拍卖。</p>'}</div><p class="modal-note">买方按眼下的生意出价，还得有足够现金接手。成交后带走 85% 客户和全部员工，其余客户另找供应商；旧债由公司先清偿。价款已经包括经营资产，不会再另卖一次。</p>`:`<p class="modal-note">设备按折旧后价值的 45%、营运资产按账面估算的 55%、知识产权按估算的 30% 出售。买家只拿资产，不接客户。以下是拍卖估价，最后留给股东的还要扣费用和债务。</p>${q.assets?`<div class="cost-breakdown">${q.assets.map(a=>`<span>${esc(a.name)} · ${pct(a.discount)} 回收 <b>${num(a.proceeds)} 万</b></span>`).join('')}</div>`:''}`}${q.grossPool!==undefined?`${liquidationWaterfall(q)}<p class="modal-note">处置费为出售回款的 ${pct(q.feeRate)}，最低 2 万、最多以清算池为限。${mode==='business'?'接收客户 '+whole(q.transferred)+'，释放客户 '+whole(q.released)+'。':'所有客户回到行业待匹配池。'}本基金累计投入 ${num(c.invested)} 万，预计收回 ${num(q.fundProceeds)} 万（${(q.fundProceeds/c.invested).toFixed(2)}×）。</p>`:''}${q.reason?`<div class="round-note">${esc(q.reason)}</div>`:''}<div class="modal-actions"><button id="cancel-liquidation">继续评估</button><button id="confirm-liquidation" class="primary" ${q.ok?'':'disabled'}>确认${liquidationNames[mode]}并终止经营</button></div>`);
 document.querySelectorAll('[data-liquidation-mode]').forEach(b=>b.onclick=()=>liquidationDesk(id,b.dataset.liquidationMode));document.querySelectorAll('[data-liquidation-buyer]').forEach(b=>b.onclick=()=>liquidationDesk(id,mode,b.dataset.liquidationBuyer));$('cancel-liquidation').onclick=close;$('confirm-liquidation').onclick=()=>{if(VC.liquidate(state,id,mode,buyerId)){close();render();showExitNotice([id]);}else liquidationDesk(id,mode,buyerId);};
}

const workoutNames={extend:'协商展期',convert:'债转股',rescue:'基金追加投资'};
function workoutHistory(c){if(!c.workouts?.length&&!c.distress)return '';return `<section class="acquisition-history"><div class="eyebrow">债务往来</div><h4>和债权人谈过的方案</h4>${c.distress?'<div class="round-note">这笔债得在今年处理完，缺口留到明年就只能清算。展期和转股都不会带来现金，钱仍不够的话，还得由基金注资。</div>':''}${c.workouts.map(a=>`<article class="acquisition-entry"><b>${a.year} · ${workoutNames[a.mode]}</b><p class="modal-note">费用 ${num(a.fee)} 万 · 基金追加 ${num(a.raise)} 万 · 债转股本金 ${num(a.converted)} 万 · 即时还本 ${num(a.principal)} 万<br>债务 ${num(a.debtBefore)} → ${num(a.debtAfter)} 万 · 持股 ${pct(a.equityBefore)} → ${pct(a.equityAfter)}<br>企业现金 ${num(a.cashBefore)} → ${num(a.cashAfter)} 万 · 基金现金 ${num(a.fundBefore)} → ${num(a.fundAfter)} 万<br>${a.resolved?'当时的现金和逾期缺口已经补上，之后仍要继续经营。':'当时缺口还在，企业仍需要现金。'}${a.changes.map(x=>`<br>贷款展期至 ${x.maturity} 年 · 新利率 ${pct(x.rate)} · 费用并入本金 ${num(x.fee)} 万`).join('')}</p></article>`).join('')}</section>`;}
function workoutDesk(id,mode='extend',amount=null){const c=state.portfolio.find(x=>x.id===id);if(!c)return;const q=VC.workoutQuote(state,id,mode,amount);modal(`<div class="eyebrow">债务协商</div><h2>${esc(companyName(c))} · 这笔债怎么处理</h2>${projectTag(c)}<p>${c.distress?'债权人只等到今年年底。钱和到期本金还没安排好，明年就会清算。':'现金不够覆盖周转和下期本息时，可以提前和债权人谈，也可以由基金补钱。'}到了 ${VC.endYear(state)} 年，就不再另留协商时间。</p><div class="financing-options" role="group" aria-label="危机处置方案">${Object.entries(workoutNames).map(([key,label])=>`<button data-workout-mode="${key}" aria-pressed="${mode===key}" class="${mode===key?'primary':''}">${label}</button>`).join('')}</div>${q.debt!==undefined?`<div class="operating-metrics"><div><label>企业现金 / 万</label><b>${num(c.cash)}</b></div><div><label>未偿本金 / 万</label><b>${num(q.debt)}</b></div><div><label>逾期本金 / 万</label><b>${num(q.due)}</b></div><div><label>基金可用 / 万</label><b>${num(state.cash)}</b></div></div><section class="financing-plan"><h4>${workoutNames[mode]} · 对方开出的条件</h4><div class="cost-breakdown"><span>处置费用 <b>${num(q.fee)} 万</b></span><span>基金付款 <b>${num(q.raise)} 万</b></span><span>处置后债务 <b>${num(q.afterDebt)} 万</b></span><span>处置后现金 <b>${num(q.afterCash)} 万</b></span><span>基金持股变化 <b>${pct(q.equity)} → ${pct(q.afterEquity)}</b></span><span>下期本息估算 <b>${num(q.service)} 万</b></span></div><p class="modal-note">${mode==='extend'?`每笔贷款只延一次，最多多两年，最晚到 ${VC.endYear(state)} 年。年利率多 2 个百分点、最高 24%，另有本金 2% 的手续费滚进贷款。这不是一笔新钱，没获展期的部分仍按原计划还。`:mode==='convert'?`债权人拟把剩余本金 ${num(q.converted)} 万和 2% 手续费换成股份，按投前 ${num(q.pre)} 万的折价估值谈。转掉的债不用再还本付息，你的持股会减少。公司没有新现金进来；经营太差，债权人也不愿换。`:`由基金独自补这笔钱，按投前 ${num(q.pre)} 万的折价估值换取新增股权。先付 2% 手续费，再补缺口、还到期本金，剩下留着周转和偿债。基金持股会提高，也会有更多钱押在这家公司。`}</p>${q.changes.map(x=>`<p class="modal-note">到期 ${x.maturity} 年 · 剩余 ${x.remaining} 年 · 新年利率 ${pct(x.rate)} · 本金增加 ${num(x.fee)} 万。</p>`).join('')}${mode==='rescue'&&q.minimum>0?`<div class="financing-options" aria-label="救助金额">${[1,1.5,2].map(k=>{const n=Math.ceil(q.minimum*k*10)/10;return `<button data-rescue-amount="${n}" ${state.cash<n?'disabled':''}>${k===1?'最低救助':k+' 倍缓冲'} · ${num(n)} 万</button>`;}).join('')}</div>`:''}</section><p class="modal-note">${q.resolves?'按这个方案办，眼前的现金和逾期本金缺口能补上。':'单靠这个方案还补不上缺口，之后仍要由基金补钱，否则明年清算。'}今年最多谈一次债务方案、做一次基金救助，可以先重组再注资。签完后，旧的普通跟投就结束了，今年也先不转让、不做新并购。</p>`:''}${q.reason?`<div class="round-note">${esc(q.reason)}</div>`:''}<div class="modal-actions"><button id="cancel-workout">回到投资组合</button><button id="confirm-workout" class="primary" ${q.ok?'':'disabled'}>确认${workoutNames[mode]}</button></div>${workoutHistory(c)}`);document.querySelectorAll('[data-workout-mode]').forEach(b=>b.onclick=()=>workoutDesk(id,b.dataset.workoutMode));document.querySelectorAll('[data-rescue-amount]').forEach(b=>b.onclick=()=>workoutDesk(id,'rescue',Number(b.dataset.rescueAmount)));$('cancel-workout').onclick=close;$('confirm-workout').onclick=()=>{if(VC.workout(state,id,mode,amount)){render();if(c.distress)workoutDesk(id,'rescue');else act('record',id);toast(c.distress?'方案已经签了，现金和到期本金还得继续补。':'方案已经签了，眼前这笔债安排好了。');}else{workoutDesk(id,mode,amount);toast('这笔债的条件有变化，得重新核一下方案。');}};}
function financingHistory(c){if(!c.loans?.length&&!c.acquisitions?.some(a=>a.equityRaise))return '';return `<section class="acquisition-history"><div class="eyebrow">借款与股权</div><h4>并购融资与偿债</h4><p class="modal-note">未偿本金 ${num(VC.debtBalance(c))} 万 · 下期预计本息 ${num(VC.debtService(c))} 万。股权估值已扣除未偿本金；股权退出不会再次扣债。${c.status!=='active'?'以下为本基金退出时的融资档案。':''}</p>${(c.loans||[]).map(l=>`<article class="acquisition-entry"><div class="portfolio-top"><b>${esc(companyRef(l.targetName))} · 并购贷款</b><span class="status-tag">${l.defaulted?'偿债违约':l.balance<.000001?((l.convertedPrincipal||0)>0?'债务已结清（含转股）':'已还清'):l.remaining+' 年待还'}</span></div><div class="cost-breakdown"><span>初始贷款 <b>${num(l.original)} 万</b></span><span>固定年利率 <b>${pct(l.rate)}</b></span><span>未偿本金 <b>${num(l.balance)} 万</b></span><span>累计还本 <b>${num(l.paidPrincipal)} 万</b></span><span>已转股本金 <b>${num(l.convertedPrincipal||0)} 万</b></span><span>资本化展期费 <b>${num(l.capitalizedFees||0)} 万</b></span><span>到期年度 <b>${l.originYear+l.term}</b></span><span>未付到期本金 <b>${num(l.due)} 万</b></span></div></article>`).join('')}${c.acquisitions.filter(a=>a.equityRaise>0).map(a=>`<p class="modal-note">${a.year} · ${esc(companyRef({id:a.targetId,name:a.targetName}))} 并购外部增资 ${num(a.equityRaise)} 万，成交时基金持股 ${pct(a.equityBefore)} → ${pct(a.equityAfter)}。该笔外部增资不提供基金跟投，稀释持续影响未来回款。</p>`).join('')}</section>`;}
function acquisitionHistory(c){if(!c.acquisitions?.length)return '';const m=state.markets[c.sector],b=m.members.find(x=>x.id===c.id);return `<section class="acquisition-history"><div class="eyebrow">收购记录</div><h4>买下的企业与整合进展</h4><p class="modal-note">目前客户 ${whole(b?.customers||0)} 个折算客户，占行业 ${pct((b?.customers||0)/m.total)}。历史经营报表按当年结算时点保留；并购不回改历史收入。</p>${c.acquisitions.map(a=>`<article class="acquisition-entry"><div class="portfolio-top"><b>${esc(companyRef({id:a.targetId,name:a.targetName}))}</b><span class="status-tag">${a.status} · ${a.stage}/2 年</span></div><div class="cost-breakdown"><span>收购价款 <b>${num(a.price)} 万</b></span><span>交易费用 <b>${num(a.fee)} 万</b></span><span>成交转入客户 <b>${whole(a.customers)}</b></span><span>累计整合流失 <b>${whole(a.lost)}</b></span><span>整合已经花了 <b>${num(a.spent)} 万</b></span><span>成交后企业账上 <b>${num(a.cashAfter)} 万</b></span></div>${a.events.map(e=>`<p class="modal-note">${e.year} · ${e.adverse?'执行受挫':'进展正常'} · 整合支出 ${num(e.cost)} 万 · 客户流失 ${whole(e.loss)}${e.support?' · 投后支持 L'+e.support:''}</p>`).join('')}</article>`).join('')}<p class="modal-note">整合后交付成本率下降：降低 ${(c.mergerSynergy*100).toFixed(1)} 个百分点。${c.integration?'整合期间暂停主动转让与自动退出。':'整合完成后的退出仍受经营表现与市场窗口影响。'}</p></section>`;}
function acquisitionDesk(id){const c=state.portfolio.find(x=>x.id===id);if(!c)return;const targets=VC.acquisitionTargets(state,id);modal(`<div class="eyebrow">并购案头</div><h2>${esc(companyName(c))} · 收购同行</h2>${projectTag(c)}<p>找一家同行，把生意、客户和团队接过来。价款由公司付，也可以借款或引入新股东；对方账上的现金和旧债留给卖方，基金不直接出钱。</p><div class="acquisition-budget"><label>企业可用现金</label><strong>${num(c.cash)}<small> 万元</small></strong><span>${c.integration?'上一家还没整合完，暂时不谈下一笔。':'买下来只是开始，后面两年的整合和周转也要备好钱。'}</span></div>${workoutHistory(c)}${financingHistory(c)}${acquisitionHistory(c)}<h4>可以谈的同行 · ${targets.length} 家</h4><div class="acquisition-targets">${targets.map(q=>`<article class="acquisition-target"><div><h3>${esc(companyName({id:q.targetId,name:q.targetName}))}</h3>${projectTag({id:q.targetId,name:q.targetName})}<p>${whole(q.customers)} 客户 · ${q.employees} 名员工 · 合并后份额 ${pct(q.share)}</p><span>收购价 ${num(q.price)} 万 + 交易费 ${num(q.fee)} 万</span><small>${q.ok?'企业现金可覆盖成交款与最低整合储备':'现金不足时可评估贷款或增资；'+esc(q.reason)}</small></div><button data-acq-target="${esc(q.targetId)}">看看收购条件</button></article>`).join('')||'<p class="modal-note">目前没有合适的同行可谈。已经被收购、停业和基金自己的持仓都不在这份名单里。</p>'}</div>`);document.querySelectorAll('[data-acq-target]').forEach(b=>b.onclick=()=>acquisitionConfirm(id,b.dataset.acqTarget));}
function acquisitionConfirm(id,target,mode="cash"){const c=state.portfolio.find(x=>x.id===id),q=VC.acquisitionQuote(state,id,target,mode);if(!Number.isFinite(q.due))return toast(q.reason);modal(`<div class="eyebrow">收购议案</div><h2>收购 ${esc(companyName({id:q.targetId,name:q.targetName}))}</h2>${projectTag({id:q.targetId,name:q.targetName})}<p>由 ${esc(companyRef(c))} 接手这门生意。对方的现金和旧债留给卖方；本次筹款和付款都在企业账上，基金不用直接付款。</p><div class="financing-options" role="group" aria-label="并购融资方案">${[['cash','企业现金'],['debt','并购贷款'],['equity','外部增资']].map(([key,label])=>`<button data-financing="${key}" aria-pressed="${mode===key}" class="${mode===key?'primary':''}">${label}</button>`).join('')}</div><div class="operating-metrics"><div><label>收购价款 / 万</label><b>${num(q.price)}</b></div><div><label>交易费用 / 万</label><b>${num(q.fee)}</b></div><div><label>立即支付 / 万</label><b>${num(q.due)}</b></div><div><label>成交后企业现金 / 万</label><b>${num(q.remaining)}</b></div></div><section class="financing-plan"><h4>${mode==='debt'?'贷款方案':mode==='equity'?'增资方案':'现金方案'}</h4><div class="cost-breakdown"><span>新增贷款 <b>${num(q.loan)} 万</b></span><span>外部增资 <b>${num(q.equityRaise)} 万</b></span><span>成交前持股 <b>${pct(q.equityBefore)}</b></span><span>成交后持股 <b>${pct(q.equityAfter)}</b></span></div><p class="modal-note">${mode==='debt'?`按双方业务和现有债务，最多可贷 ${num(q.capacity)} 万，且不超过收购价的 65%。固定年利率 ${pct(q.rate)}，${q.term} 年等额本金；首年预计本息 ${num(q.annualService)} 万，最后到期 ${state.year+q.term} 年。利息按年初本金付，记在成本里；还本金从现金走。到期还不上会先尝试融资。最终缺口补不上，就得清算，股东排在债权人后面。`:mode==='equity'?`这轮按投前 ${num(q.preMoney)} 万向外部投资人募资，只补收购和储备的缺口，最多募投前估值的 80%。对方还要看经营是否过关。这一轮不让基金跟投，新股东此后也会分走退出回款。`:'直接用公司账上的钱付，不借新债，也不引入新股东。'}${q.loan+q.equityRaise===0&&mode!=='cash'?' 当前现金足够，无需新增融资。':''}</p></section><div class="acquisition-terms"><h4>客户和团队怎么接过来</h4><p>接过 ${whole(q.customers)} 个折算客户和 ${q.employees} 名员工，合并后份额为 ${pct(q.share)}。双方价格按原客户规模合并，收入从下一份年报算起；客户接过来后，也得继续留住。</p><h4>接下来的两年</h4><p>整合预算共 ${num(q.planned)} 万；两年都不顺，可能花到 ${num(q.worst)} 万，都要记进经营成本。每年执行受挫的风险约 ${pct(q.risk)}。有人盯投后时，每级可减少 4 个百分点，最低 6%。正常年约有 2%—6% 的剩余并购客户离开；遇到困难则约 18%—34%，这些客户会重新找供应商。</p><p>团队接过来后，工资也要继续付。两年都顺利，这笔并购会让交付成本率少 1.5 个百分点，历次合计最多少 6 个百分点；受挫就没有这项节省。整合没结束，暂不办理股权转让和退出。</p><p>成交后至少留下 ${num(q.reserve)} 万，里面包括首年还债的钱，之后若继续亏损还得另想办法。收购来的业务先按价款的 65% 入估值，后面再看经营重估。${VC.endYear(state)-1} 年起不再谈新并购。</p></div>${q.reason?`<div class="round-note">${esc(q.reason)}。企业当前现金 ${num(q.cash)} 万，本次需至少 ${num(q.required)} 万。</div>`:''}<div class="modal-actions"><button id="cancel-acquisition">回到收购名单</button><button class="primary" id="confirm-acquisition" ${q.ok?'':'disabled'}>确认收购 · ${num(q.due)} 万</button></div>`);document.querySelectorAll('[data-financing]').forEach(b=>b.onclick=()=>acquisitionConfirm(id,target,b.dataset.financing));$('cancel-acquisition').onclick=()=>acquisitionDesk(id);$('confirm-acquisition').onclick=()=>{if(VC.acquire(state,id,target,mode)){close();render();toast('并购已成交，客户和员工已转入，两年整合期开始。');}else{toast('并购条件已变化，请重新评估。');acquisitionDesk(id);}};}


function financeDetails(c){const r=c.financialHistory.at(-1);return `${financeSummary(c)}${ventureRiskPanel(c)}${capitalHistory(c)}<p class="company-update">${r.year} 年${r.opening?'期初资料':'经营结算'}：利润 ${signed(r.profit)} 万，资本开支 ${num(r.capex)} 万${r.workingCapital>0?'，新增周转占用 '+num(r.workingCapital)+' 万':''}，经营后净现金流 ${signed(r.cashFlow)} 万。${VC.debtBalance(c)>0?'目前贷款余额 '+num(VC.debtBalance(c))+' 万。':''}</p>${c.pendingDividend||c.pendingRebuildExpense||c.pendingRebuildCapex||c.pendingAllocationPrincipal?'<p class="modal-note">今年新付的分红、还本或项目款已经走账，下一份年报会列出来。</p>':''}<details class="detail-finance"><summary>翻开账本与交易档案</summary>${fullFinanceDetails(c)}</details>`;}
function decisionAgenda(){
 const events=VC.capitalMilestones(state),tasks=VC.fundTasks(state);if(!events.length&&!tasks.length)return '';
 return `<section class="decision-agenda" aria-label="本年投资事务">${events.length?`<div class="capital-news"><div class="eyebrow">${state.year} · 融资与发行动态</div>${events.map(x=>`<article><h3>${esc(archiveText(x.title))}</h3><p>${esc(archiveText(x.text))}</p><button data-action="capital" data-id="${esc(x.id)}">核对股份与条款</button></article>`).join('')}</div>`:''}${tasks.length?`<details class="fund-tasks" ${tasks.some(x=>x.kind==='debt')?'open':''}><summary>本年待办 ${tasks.length} 项${tasks.some(x=>x.kind==='debt')?' · 有到期债务需处理':''}</summary><div class="task-list">${tasks.map(x=>`<article><div><b>${esc(archiveText(x.title))}</b><p>${esc(archiveText(x.text))}</p></div><button data-action="${x.action}" data-id="${esc(x.id)}">${({follow:'核对认购',offer:'评估报价',debt:'处理债务',dividend:'安排分配'})[x.kind]}</button></article>`).join('')}</div></details>`:''}</section>`;
}
function partnerLetter(){
 const years=state.year-1990;if(state.ended||years<=0||years%10)return '';
 const themes={10:'从第一批样品走到商业化，开始看清订单与估值的距离。',20:'两轮产业更替之后，能留下来的经营回款比热度更有分量。',30:'企业的名字换了几轮，现金、交付与客户仍要逐一核查。',40:'新的产业机会已经进入档案，过去的经验也需要重新验证。',50:'回看半世纪的判断，基金仍要给新机会和后续经营留钱。'};
 return `<details class="partner-letter"><summary>第 ${years} 年 · 合伙人手记</summary><p>${themes[years]||''}本局已投资 ${state.portfolio.length} 家企业，累计退出与减持回款 ${num(state.returned-state.dividends)} 万，收到分红 ${num(state.dividends)} 万。往年的每次投入与回款仍留在档案中。</p></details>`;
}
function yearReview(){const list=VC.annualReview(state);return list.length?`<section class="year-review" aria-label="年度回顾"><div class="review-heading"><h2>${state.year} 年 · 年度纪要</h2></div><div class="review-grid">${list.map(x=>`<article><h3>${esc(archiveText(x.title))}</h3><p>${esc(archiveText(x.text))}</p><button data-action="${x.action||'record'}" data-id="${x.id}">去看看</button></article>`).join('')}</div></section>`:'';}
const thesisNames={cash:'经营能持续产生现金',growth:'客户和收入还能继续增长',product:'产品改进能形成竞争力'};
function exitDecisionRecap(c){const ds=c.exitDecisions?.filter(x=>!x.accepted);if(!ds?.length)return '';const last=ds.at(-1),extra=c.invested-last.invested,later=c.dividendReceived-last.dividends,years=(c.exitReview?.year??c.founded+c.age)-last.year,net=c.proceeds+later-extra,delta=net-last.quote;return `<p>你曾在 ${ds.slice(0,3).map(d=>d.year+' 年放弃 '+num(d.quote)+' 万报价').join('、')}${ds.length>3?'等 '+ds.length+' 次':''}。最后一次没有卖，${years?'又持有 '+years+' 年':'同年稍后退出'}，此后追加 ${num(extra)} 万，另收分红 ${num(later)} 万，最终退出收回 ${num(c.proceeds)} 万。按名义金额扣回追加投入，后续净回款比最后那次报价${Math.abs(delta)<.05?'基本持平':(delta>=0?'多 ':'少 ')+num(Math.abs(delta))+' 万'}。</p>`;}
function exitProjects(c){const ps=c.rebuilds||[];if(!ps.length)return c.thesis?.kind==='product'?'<p>当初看好产品，持有期间没有批准新的研发、产能或渠道项目。</p>':'';const done=ps.filter(p=>p.status==='已完成').length,stopped=ps.filter(p=>p.status!=='已完成').length;return `<p>持有期间，你批准 ${ps.length} 个再投资项目，${done?'完成 '+done+' 个':''}${done&&stopped?'，':''}${stopped?'终止 '+stopped+' 个':''}。预算合计 ${num(ps.reduce((n,p)=>n+p.budget,0))} 万，公司实际花费 ${num(ps.reduce((n,p)=>n+p.spent,0))} 万。${ps.map(p=>p.year+' 年的'+VC.rebuildTypes[p.type]+(p.status==='已完成'?'已经做完':'中途终止')).join('；')}。</p>`;}
function exitFollow(c){const rs=VC.followRecords(c);if(!rs.length)return '';const years=[...new Set(rs.map(x=>x.year))],sameYear=c.exitReview?.year===years.at(-1);return `<p>你在 ${years.join('、')} 年按比例跟过 ${rs.length} 轮融资。${sameYear&&c.status==='股权转让'?'最后这一轮跟投之后，你在同一年转让了股权。':c.status==='失败清算'?'跟投保住了当轮的持股比例，企业后来仍走到了清算。':''}</p>`;}
function exitRecap(c){const r=c.exitReview||VC.exitReview(c,Math.min(state.year,c.founded+c.age)),gain=c.proceeds+c.dividendReceived-c.invested;const outcome=c.thesis?.kind==='growth'?(r.revenueEnd>r.revenueStart?(gain>=0?'收入后来增长，最终也收回了本金。':'收入后来增长了，回款却没收回全部本金。'):'收入没有超过买入时，当初期待的增长没等到。'):c.thesis?.kind==='cash'?(c.dividendReceived>0?`分红一共收回 ${num(c.dividendReceived)} 万，占累计投入 ${pct(c.dividendReceived/c.invested)}。${gain<0?'分过红，仍没能收回全部本金。':'余下回款来自退出。'}`:(VC.exitReceipt(c).prior>0?'持有期间没有收到分红，回款来自历次减持及最后退出。':'持有期间没有收到分红，回款全部来自最后退出。')):'';return `<section class="exit-recap"><h3>这笔投资结案了</h3><p>${c.thesis?'当初的判断是：'+thesisNames[c.thesis.kind]+'。':'这笔旧投资没有留下当初的投资理由。'}持有 ${r.years} 年，收入从 ${num(r.revenueStart)} 万走到 ${num(r.revenueEnd)} 万。</p><div class="cost-breakdown"><span>累计投入 <b>${num(c.invested)} 万</b></span><span>退出回款 <b>${num(c.proceeds)} 万</b></span><span>历史分红 <b>${num(c.dividendReceived)} 万</b></span><span>项目净回款 <b>${signed(gain)} 万</b></span></div><p>退出与分红合计 ${((c.proceeds+c.dividendReceived)/c.invested).toFixed(2)} 倍投入。${outcome}${r.funding>0?'持有期间，公司另募到 '+num(r.funding)+' 万；历次持股变化见融资档案。':''}</p>${exitProjects(c)}${exitFollow(c)}${exitDecisionRecap(c)}<p class="modal-note">这是这一笔投资的回款；基金团队、尽调和日常运营费用，还要另算。</p></section>`;}
function boardDesk(id){const c=state.portfolio.find(c=>c.id===id),q=VC.companyCase(state,id);if(!q)return toast('这家企业眼下没有新的董事会来信。');const f=VC.companyIdentity(c);modal(`<div class="eyebrow">${esc(companyName(c))} · 董事会来信</div><h2>${esc(q.title)}</h2>${projectTag(c)}<p>${esc(q.text)}</p><h4>${q.canInvest?'拿 '+num(q.quote.budget)+' 万'+(q.kind==='rnd'?'改进产品':q.kind==='capacity'?(['精密制造','消费品牌','通信设备','生物科技','清洁能源'].includes(c.sector)?'扩建产能':'补足交付能力'):'去拓展客户'):'这次先不追加预算'}</h4><p>${q.canInvest?'企业付款后剩余 '+num(q.quote.cashAfter)+' 万。计划分两阶段，可能延期或超支。':''}${q.canInvest?(q.kind==='rnd'?'产品改进会逐步增强获客能力、降低交付成本。':q.kind==='capacity'?'交付能力补上以后，还要承担后续维护开支。':'渠道拓展会增加获客能力，也会增加人员和持续开支。')+'每年约有 '+pct(q.quote.risk)+' 的可能遇到执行困难，客户和订单仍要自己争取。':''}${q.quote.reason?esc(q.quote.reason)+'。':''}</p><div class="modal-actions"><button id="case-wait">${esc(q.waitLabel||'暂不追加投入')}</button><button id="case-defend">${esc(q.alternative)}</button>${q.canInvest?'<button class="primary" id="case-invest">投入 '+num(q.quote.budget)+' 万</button>':''}</div>`);for(const choice of ['wait','defend','invest'])if($('case-'+choice))$('case-'+choice).onclick=()=>{if(VC.resolveCase(state,id,choice)){close();render();toast(choice==='invest'?'预算批下去了，等企业来年报进展。':'这次董事会就按你的意见办。');}};}
function offerDesk(id){const c=state.portfolio.find(c=>c.id===id),o=VC.exitQuote(state,id);if(!o)return toast('买方的这份报价已经过期了。');modal(`<div class="eyebrow">${esc(companyName(c))} · 退出报价</div><h2>这份报价，接不接？</h2>${projectTag(c)}<p>对方提出${o.status}，基金可收到 ${num(o.value)} 万；加上已收分红 ${num(c.dividendReceived)} 万，总回款为 ${((o.value+c.dividendReceived)/c.invested).toFixed(2)} 倍投入。你已经持有 ${c.age} 年。</p><div class="exit-context"><p>接受后基金现金从 ${num(state.cash)} 万增至 ${num(state.cash+o.value)} 万，可以再找项目，也可以留给跟投和团队。企业今年净现金流 ${signed(c.cashFlow)} 万，收入增速 ${signed(c.organicGrowth??c.growth)}%。</p><p>这次不卖，${num(o.value)} 万就还没回到基金；企业的现金也仍留在企业。</p></div><p>买方只等今年答复。卖掉以后，后面的好坏都不再属于基金；留下来，就得继续等经营和下一次出价。今年若再有分红或股权变动，买方会按变化后的权益重新报价。</p><div class="modal-actions"><button id="offer-wait">这次不卖</button><button class="primary" id="offer-accept">接受 · ${num(o.value)} 万到账</button></div>`);for(const accept of [false,true])$(accept?'offer-accept':'offer-wait').onclick=()=>{if(VC.decideExit(state,id,accept)){close();render();if(accept)showExitNotice([id]);else toast('已放弃本次报价，企业继续经营。');}else{close();render();toast('企业刚有新的交易，这份报价得再核一下。');}};}

function teamPage(){const total=VC.payroll(state),b=state.expenseBreakdown;return `<div class="team-overview"><div><div class="eyebrow">基金团队</div><h2>基金需要几位同事。</h2><p>新同事入职，先付招聘费和这一年的薪酬。年末继续合作就续付下一年；账上不够会暂时停工。已付薪酬不退，同年请回来也不再收一遍。在岗尽调专家的项目尽调已含薪酬，不另收费。</p></div><div class="team-budget"><label>${state.ended?'已停止续聘':'下期团队薪酬'}</label><strong>${state.ended?'0.0':num(total)}<small> 万 / 年</small></strong><span>累计薪酬 ${num(b.payroll)} 万<br>招聘与培训 ${num(b.recruiting+b.training)} 万</span></div></div><div class="team-grid">${Object.entries(VC.roles).map(([key,r])=>{const t=state.team[key],main=t.level?(t.active?'upgrade':'resume'):'hire',q=VC.teamQuote(state,key,main);return `<article class="team-card"><div class="eyebrow">${r.code}</div><h3>${r.name}<span class="status-tag">${t.level?'L'+t.level+' · '+(state.ended?'已结项':t.active?'服务中':'已暂停'):'待招聘'}</span></h3><p>${r.description}</p><div class="team-stats"><span>累计服务 <b>${t.years} 年</b></span><span>当前年薪 <b>${t.level?r.salary[t.level]:r.salary[1]} 万</b></span></div><div class="level-track">${[1,2,3].map(n=>`<span class="${t.level>=n?'filled':''}">L${n}<small>${r.salary[n]} 万 / 年</small></span>`).join('')}</div><p class="modal-note">${t.level===3?(t.years>=30?'已合作三十年以上，经历过多轮产业周期。':t.years>=20?'已合作二十年以上，长期经验仍在本岗发挥作用。':t.years>=10?'已合作十年以上，已是团队的长期骨干。':'已是最高职级，继续服务会保留累计资历。'):t.level?'晋升到 L'+(t.level+1)+' 需累计服务 '+(t.level===1?1:3)+' 年。':'招聘费 '+r.entry+' 万 + 本期薪酬 '+r.salary[1]+' 万。'}${q.reason?' '+esc(q.reason):''}</p><div class="team-actions"><button class="primary" data-role="${key}" data-team-action="${main}" ${q.ok?'':'disabled'}>${main==='hire'?'招聘':main==='upgrade'?'晋升':'恢复服务'}${q.ok?' · '+num(q.cost)+' 万':''}</button>${t.active&&!state.ended?`<button data-role="${key}" data-team-action="pause">暂停合作</button>`:''}</div></article>`;}).join('')}</div><div class="team-policy"><b>团队的分工</b><p>研究员多跑行业，带回额外项目；尽调专家核查材料，把能力判断做得细一些，无法提前知道尚未发生的事。投后经理先去现金最紧的 3 / 6 / 10 家企业，帮忙接客户、留客户、压成本。退出顾问去联系买方，谈价格。</p><details><summary>聘用条款与工作范围</summary><p>投后经理每级使获客吸引力增加 8%、流失率减少 1.2 个百分点，同时改善部分成本；跟进并购时，每级减少 4 个百分点的整合受挫风险。退出顾问每级增加 2.5 个百分点的撮合机会，转让和清算的具体折价见交易方案。</p><p>年末按研究、尽调、投后、退出的顺序续付薪酬。余额不够的岗位暂停，资历保留；基金结案后不再续聘。</p></details></div>`;}
function teamAction(key,action){const q=VC.teamQuote(state,key,action),r=VC.roles[key];if(!q.ok)return;modal(`<div class="eyebrow">人事安排</div><h2>${action==='pause'?'暂停':action==='hire'?'招聘':action==='upgrade'?'晋升':'恢复'}${r.name}？</h2><p>${action==='pause'?'这位同事从现在起停工，已有资历保留。本年付过的薪酬不退，同年请回来不用再付一遍。':`本次支付 ${num(q.cost)} 万元，其中招聘 / 培训费 ${num(q.fee)} 万、本期薪酬 ${num(q.salary)} 万。之后每期薪酬 ${q.annual} 万元，将于下一次年度经营完成后自动续付；现金不足则暂停。`}${key==='diligence'&&action!=='pause'?'在岗期间项目尽调免费，项目池内已尽调报告会自动补全到当前专家等级。':''}</p><div class="modal-actions"><button id="cancel">取消</button><button class="primary" id="confirm-team">确认${action==='pause'?'暂停':action==='hire'?'招聘':action==='upgrade'?'晋升':'恢复'}</button></div>`);$('cancel').onclick=close;$('confirm-team').onclick=()=>{if(VC.manageTeam(state,key,action)){close();render();toast('人事安排已经办好。');}};}
function historicalNote(c){const p=VC.scenarioProject(c);if(!p)return '';const terms=VC.investmentTerms(c,state);return `<p class="financing-terms">${c.status==='available'?'认购截止：'+p.year+' 年末':'认购年份：'+p.year+' 年'} · ${terms.minimum} 万起投 · 本轮持股上限 ${pct(terms.maxEquity)}</p>`;}
const PROJECT_ART={
 '企业软件':{file:'software',groups:[['车间排产软件','多工厂协同排产系统'],['经销商进销存系统','跨区域供应链软件'],['连锁门店财务系统','企业智能流程管理']]},
 '精密制造':{file:'manufacturing',groups:[['精密传动部件','高精度传感部件'],['工业视觉检测设备'],['小型自动化产线','柔性机器人工作站','自动化装配单元']]},
 '消费品牌':{file:'consumer',groups:[['区域食品品牌','个性化营养食品'],['家庭清洁用品','可循环日用消费品'],['户外日用品','适老家庭用品']]},
 '通信设备':{file:'telecom',groups:[['园区通信设备','工业边缘通信设备','园区感知网络'],['运营商传输模块','低能耗传输模块'],['企业接入设备']]},
 '互联网':{file:'internet',groups:[['工业品交易平台','工业服务交易平台','再制造设备交易平台'],['本地商户服务平台'],['垂直信息订阅服务','专业服务协作平台']]},
 '生物科技':{file:'biotech',groups:[['临床检测试剂','精准诊断试剂'],['实验室诊断设备','家庭检测设备'],['生物工艺耗材','细胞工艺耗材']]},
 '移动应用':{file:'mobile',groups:[['门店预约应用','居家照护协作应用','社区服务应用'],['移动协作工具','设备运维调度应用'],['城市配送应用']]},
 '清洁能源':{file:'energy',groups:[['工商业储能控制器','储能寿命管理设备'],['电池检测设备','电池回收检测设备'],['分布式能源管理系统','园区微网调度系统']]},
 '人工智能':{file:'ai',groups:[['工业质检模型','机器人任务规划工具'],['文档处理工具','工业设计辅助系统'],['客服辅助系统','企业智能体运维工具']]}
};
const REAL_PROJECT_ART=['kingsoft','tencent','alibaba','byd','baidu','jd','leshi','xiaomi','meituan','catl','bytedance','luckin'];
function companyArtwork(c){
 const real=VC.historicalProject(c),realIndex=real?REAL_PROJECT_ART.indexOf(real.key):-1;
 if(realIndex>=0)return {file:'art/projects-historical.webp',key:'real-'+real.key,index:realIndex,cols:3,rows:4};
 const data=PROJECT_ART[c.sector]||PROJECT_ART['企业软件'],product=VC.companyIdentity(c).product;
 let group=data.groups.findIndex(g=>g.includes(product));if(group<0)group=0;
 const parts=/^(\d{4})-(\d+)$/.exec(c.id),fallback=[...String(c.id)].reduce((h,x)=>(Math.imul(h,31)+x.charCodeAt(0))>>>0,0);
 const variant=parts?(Number(parts[1])+Number(parts[2])-1)%3:fallback%3,index=group*3+variant;
 return {file:'art/projects-'+data.file+'.webp',key:data.file+'-'+index,index,cols:3,rows:3};
}
const PROJECT_ART_KEY=KEY+'-illustrations-v1';let projectArtChoices=null;
function projectArtSignature(c){return JSON.stringify([c.id,c.name,c.sector,VC.companyIdentity(c).product]);}
function artChoices(){
 if(!projectArtChoices){try{const rows=JSON.parse(localStorage.getItem(PROJECT_ART_KEY)||'[]');projectArtChoices=new Map(Array.isArray(rows)?rows.filter(r=>Array.isArray(r)&&typeof r[0]==='string'&&r[0].length<1000&&Number.isInteger(r[1])&&r[1]>=0&&r[1]<9).slice(-1024):[]);}catch{projectArtChoices=new Map();}}
 return projectArtChoices;
}
function companyArtworkForView(c){
 const a=companyArtwork(c),index=artChoices().get(projectArtSignature(c));
 return a.rows===3&&Number.isInteger(index)&&Math.floor(index/3)===Math.floor(a.index/3)?{...a,index,key:a.key.replace(/\d+$/,String(index))}:a;
}
function prepareCompanyArt(){
 const choices=artChoices(),front=[...state.portfolio.filter(c=>c.status==='active'),...state.deals].sort((a,b)=>a.id.localeCompare(b.id)),used=new Set();let changed=false;
 for(const c of front){const a=companyArtworkForView(c);if(choices.has(projectArtSignature(c)))used.add(a.key);}
 for(const c of [...front,...state.portfolio.filter(c=>c.status!=='active')]){
  const signature=projectArtSignature(c),base=companyArtwork(c);if(base.rows!==3)continue;
  const old=choices.get(signature);if(Number.isInteger(old)&&Math.floor(old/3)===Math.floor(base.index/3)){used.add(companyArtworkForView(c).key);continue;}
  const candidates=[0,1,2].map(n=>Math.floor(base.index/3)*3+(base.index+n)%3),active=front.includes(c);
  const index=active?candidates.find(n=>!used.has(base.key.replace(/\d+$/,String(n))))??base.index:base.index;
  choices.set(signature,index);used.add(base.key.replace(/\d+$/,String(index)));changed=true;
 }
 while(choices.size>1024){choices.delete(choices.keys().next().value);changed=true;}
 if(changed&&projectArtCacheWritable&&!saveError)try{localStorage.setItem(PROJECT_ART_KEY,JSON.stringify([...choices]));}catch{/* A cosmetic cache never blocks financial saves or play. */}
}
let projectImageObserver=null;const pendingProjectImages=new Set();
function startProjectImage(img){
 if(!img.isConnected)return;
 pendingProjectImages.delete(img);projectImageObserver?.unobserve(img);
 const frame=img.closest('.project-art'),button=frame?.querySelector('[data-art-retry]');
 frame?.classList.remove('art-failed');if(button)button.hidden=true;
 img.dataset.artState='loading';const attempt=Number(img.dataset.artAttempt||0);
 img.src=img.dataset.artSrc+(attempt?'?retry='+attempt:'');
}
function prepareProjectImages(){
 document.documentElement?.style?.setProperty('--art-density',String(Math.max(1,window.devicePixelRatio||1)));
 for(const img of pendingProjectImages)if(!img.isConnected){projectImageObserver?.unobserve(img);pendingProjectImages.delete(img);}
 if(!projectImageObserver&&typeof IntersectionObserver==='function')projectImageObserver=new IntersectionObserver(entries=>{
  for(const entry of entries)if(entry.isIntersecting)startProjectImage(entry.target);
 },{rootMargin:'320px 0px'});
 for(const img of document.querySelectorAll('img[data-art-src]')){
  if(img.tagName!=='IMG'||img.dataset.artBound)continue;img.dataset.artBound='1';img.dataset.artAttempt='0';
  const frame=img.closest('.project-art'),button=frame?.querySelector('[data-art-retry]');
  img.addEventListener('load',()=>{if(img.naturalWidth>0){img.dataset.artState='ready';frame?.classList.remove('art-failed');if(button)button.hidden=true;}});
  img.addEventListener('error',()=>{
   if(Number(img.dataset.artAttempt)===0){img.dataset.artAttempt='1';startProjectImage(img);return;}
   img.dataset.artState='error';frame?.classList.add('art-failed');if(button)button.hidden=false;
  });
  if(button)button.onclick=e=>{e.stopPropagation();img.dataset.artAttempt=String(Number(img.dataset.artAttempt)+1);startProjectImage(img);};
  if(img.loading==='eager'||!projectImageObserver)startProjectImage(img);
  else{img.dataset.artState='pending';pendingProjectImages.add(img);projectImageObserver.observe(img);}
 }
}
