function capitalHistory(c){
 const f=c.capital;if(!f)return '';return `<details class="capital-archive"><summary>融资与减持记录 · ${f.history.length+(f.trades?.length||0)} 笔</summary><section class="acquisition-history"><div class="eyebrow">融资与股权</div><h4>${f.public?'上市公司 · 公开市场阶段':esc(VC.fundingStages[f.stage].name)}</h4>${f.history.length?'<div class="capital-history">'+[...f.history].reverse().map(r=>r.kind==='follow'?`<article><b>${r.year} · 跟投交割</b><p>基金支付 ${num(r.fundAmount)} 万，承接本轮原比例份额。企业融资此前已到账，本次不重复增加公司现金。持股 ${pct(r.equityBefore)} → ${pct(r.equityAfter)}。</p></article>`:`<article><b>${r.year}${r.pricing==='down'?' · 低估值融资':''} · ${r.kind==='bridge'?'过桥融资':r.kind==='placement'?'上市后增发':VC.fundingStages[r.stage].name}</b><p>本轮募资 ${num(r.raise)} 万，基金认购 ${num(r.fundAmount)} 万；投前 ${num(r.preValue)} 万，投后 ${num(r.postValue)} 万${r.fee?'，发行费 '+num(r.fee)+' 万':''}。持股 ${pct(r.equityBefore)} → ${pct(r.equityAfter)}。</p><p>${esc(r.purpose)}</p></article>`).join('')+'</div>':'<p>此前融资没有单列轮次，原有投入、现金和股份均按原账保留。</p>'}${f.resource?`<p>产业协同计划 · 协调费用 ${num(f.resource.fee)} 万由基金承担。资源由同行业盈利持仓协调对接，投后团队负责执行；能否成交仍取决于产品、价格与交付。${f.resource.lastResult?esc(f.resource.lastResult)+'。':''}</p>`:''}${f.public?`<p>上市年份 ${f.public.year} · 当前未解锁股份 ${pct(VC.publicQuote(state,c.id).locked||0)}，可流通持股 ${pct(VC.publicQuote(state,c.id).available||0)}。${f.application?'上市前准备支出 '+num(f.application.fee)+' 万。':''}</p>`:f.application?`<p>${f.application.year} 年启动发行准备 · ${f.application.status==='review'?'材料与经营核查中，尚未完成发行':f.application.status==='withdrawn'?'暂缓推进，整改后再议':'已完成发行'}；已付准备费 ${num(f.application.fee)} 万，不因暂缓而退还。</p>`:''}${f.trades?.length?'<h4>公开市场减持</h4>'+f.trades.map(r=>`<p>${r.year} 年卖出 ${pct(r.equity)} 股权，费用 ${num(r.fee)} 万，到账 ${num(r.proceeds)} 万。</p>`).join(''):''}</section></details>`;
}
