 $('investment-cancel').onclick=()=>detail(id,thesis,mode);$('investment-confirm').onclick=()=>{const b=$('investment-confirm');b.disabled=true;if(VC.invest(state,id,amount,thesis,mode)){close();render();toast('本轮认购已交割，现金与股份已入账。');}else{capitalInvestmentConfirm(id,amount,thesis,mode);toast('认购条件已变化，请重新核对。');}};
