function diligenceEconomics(c){
 if(c.economyVersion!==12||!c.dd)return '';const q=VC.diligenceReport(c);
 return `<section class="diligence-economics"><h4>这份要价，贵在哪里</h4><p>要价相当于年收入的 ${q.askingRevenue.toFixed(1)} 倍。按现在的经营和账上现金，我们估在 ${num(q.referenceValue)} 万；${c.value>q.referenceValue?'要价中的 '+num(c.value-q.referenceValue)+' 万，要靠以后的增长来兑现':'报价低于这份估值 '+num(q.referenceValue-c.value)+' 万，仍需核查经营与变现条件'}。尽调估计，现有团队的交付负荷约为 ${pct(q.deliveryLow)}—${pct(q.deliveryHigh)}；超过 100% 的部分会增加外包和交付费用。</p><p>若收入维持现状，均衡经营下一期约${q.base.cashFlow>=0?'留下':'消耗'} ${num(Math.abs(q.base.cashFlow))} 万现金，加速扩张约${q.expand.cashFlow>=0?'留下':'消耗'} ${num(Math.abs(q.expand.cashFlow))} 万。扩张要先招人、加大营销，订单能否补上仍取决于竞争。</p><p>若收入下降 20%，按均衡经营测算的净现金流约 ${signed(q.stressCashFlow)} 万。本息、周转占用和新交易尚未扣下；订单也未必按这个情景走。</p></section>`;
}
function portfolioCard(c){
 const active=c.status==='active',value=(active?c.value*c.equity+(c.capital?c.proceeds:0):c.proceeds)+(c.dividendReceived||0),op=VC.exitQuote(state,c.id),event=VC.companyCase(state,c.id);
 const button=(action,label)=>`<button data-action="${action}" data-id="${c.id}">${label}</button>`;
 return `<article class="portfolio-row" data-sector="${esc(c.sector)}" data-attention="${active?(c.distress?'debt':op?'offer':''):''}"><div class="portfolio-top">${companyPicture(c,'holding')}<div class="portfolio-identity"><h3>${esc(companyName(c))}</h3>${projectTag(c)}<div class="subline">${esc(c.sector)} · ${c.founded} 年投资 · 持有 ${c.age} 年</div></div><span class="status-tag">${active?(c.distress?'到期款还没安排好':op?'买方等着答复':'持有中'):esc(c.status)}</span></div>${c.capital?capitalPortfolioActions(c):''}<div class="portfolio-data"><div><label>累计投入 / 万</label><b>${num(c.invested)}</b></div><div><label>${active?'持股':'退出前持股'}</label><b>${pct(c.equity)}</b></div><div><label>${active?(c.capital?'持仓＋已收回款':'股权＋已收分红'):'退出＋分红'} / 万</label><b>${num(value)}</b></div><div><label>${active?'账面与回款 / 投入':'回款倍数'}</label><b class="${value>=c.invested?'positive':'negative'}">${(value/c.invested).toFixed(2)}×</b></div></div>${active?`<p class="company-update">${esc(VC.companyIdentity(c).product)} · 今年利润 ${signed(c.profit)} 万，净现金流 ${signed(c.cashFlow)} 万。${c.dividendReceived?'累计分红到账 '+num(c.dividendReceived)+' 万。':''}</p>`:''}${c.round?`<div class="round-note">这轮筹款用于${esc(archiveText(c.round.purpose||'补充经营资金'))}，企业已收到${Number.isFinite(c.round.raise)?' '+num(c.round.raise)+' 万':'本轮融资款'}。按本轮认购权跟投 ${num(c.round.cost)} 万，持股将达到 ${pct(VC.followQuote(state,c.id).after||c.equity)}。已售股份不恢复。</div>`:''}<div class="portfolio-actions">${button('record',active?'企业档案':'退出复盘')}${active?(c.distress?button('workout','把这笔债处理好'):op?button('offer','查看退出报价'):event?button('board','董事会来信'):button('dividend','分红与偿债')):''}${active&&c.round?button('follow','按比例跟投'):''}</div>${active?`${economicsNote(c)}<details class="more-actions"><summary>和企业商量下一步</summary><div class="portfolio-actions">${button('dividend','分红与偿债')}${button('rebuild',VC.currentRebuild(c)?'看看项目进展':'安排再投资')}${button('divest','出售部分业务 / 资产')}${VC.underPressure(c)?button('liquidation','资产出售与清算'):''}${VC.debtBalance(c)>0?button('workout','这笔债怎么处理'):''}${button('acquisition',c.integration?'查看并购整合':'找一家同行谈谈')}${c.age>=2&&!c.integration&&!c.distress&&c.workoutYear!==state.year&&c.rescueYear!==state.year&&c.divestYear!==state.year&&!VC.currentRebuild(c)?button('sell','评估股权转让'):''}</div><label class="strategy-picker">下一年经营策略<select data-strategy="${c.id}" aria-label="${esc(companyRef(c))}经营策略">${Object.entries(VC.strategies).map(([key,v])=>`<option value="${key}" ${c.strategy===key?'selected':''}>${v.name}</option>`).join('')}</select></label>${strategyPreview(c)}</details>`:''}</article>`;
}
function endingStory(cash){return '六十年过去，产业换过几轮，企业来了又走。'+(cash>=state.initial?'那些投入、回款与分红，如今都有了各自的结果。':'有些判断得到了回报，有些本金没能回来。')+'最后一年的账目已经结清，这本投资手记终于合上。';}
function result(){
 if(!state.ended)return '';const profit=state.cash-state.initial,cagr=Math.pow(state.cash/state.initial,1/60)-1,rank=[...state.portfolio].sort((a,b)=>(b.proceeds+b.dividendReceived-b.invested)-(a.proceeds+a.dividendReceived-a.invested));
 const best=rank[0],gain=c=>c.proceeds+c.dividendReceived-c.invested;
 return `<section class="result-banner"><div class="eyebrow">1990—2050 · 全篇终</div><h2>六十年，远见长存。</h2><p>${endingStory(state.cash)}</p><p>退出与减持收回 ${num(state.returned-state.dividends)} 万，分红 ${num(state.dividends)} 万；累计投入 ${num(state.invested)} 万，基金支出 ${num(state.expenses)} 万。</p><div class="result-grid"><div><label>最终现金 / 万</label><b>${num(state.cash)}</b></div><div><label>累计净收益 / 万</label><b>${signed(profit)}</b></div><div><label>资金年均增长</label><b>${pct(cagr)}</b></div></div><p class="modal-note">按最初 1,000 万、最终现金和 60 年计算，已扣基金费用；不是逐笔投资的内部收益率。</p>${best?`<p>${gain(best)>0?'回报最多的是 '+esc(companyRef(best))+'，累计净赚 '+num(gain(best))+' 万。':'没有一笔投资收回全部本金，'+esc(companyRef(best))+' 的损失最少。'}每笔投资的经过都已留在档案里。</p>`:'<p>这只基金没有投过企业，余额扣除了基金运营费用。</p>'}<div class="modal-actions"><button id="result-details">查看最后一期退出明细</button><button id="result-leaderboard">查看六十年收益榜</button></div>${state.campaign?.legacySettlement?'<p class="modal-note">这是一份接续旧版本的档案，历史成绩与升级前原件仍保留，可从基金备忘导出。</p>':''}${boardProblem?'<p class="round-note">'+esc(boardProblem)+'</p>':''}</section>`;
}
// Isolate each ending branch and verify its ledger/archive before export.
function endingBackupKey(s=state){
 const a=s.continuation||s,seed=s.continuation?a.endingSeed:s.seed;if(seed===undefined)return null;
 return KEY+'-2026-ending-'+JSON.stringify([boardRule(s),s.marketSeed,seed,a.cash,a.invested,a.returned,a.expenses,a.dividends,s.continuation?a.projects:s.portfolio.length]);
}
function matchingEndingBackup(raw,s=state){
 try{const a=VC.migrate(JSON.parse(raw)),b=s.continuation||s,count=s.continuation?b.projects:s.portfolio.length;
  return a.ended&&a.year===2026&&!a.continuation&&boardRule(a)===boardRule(s)&&a.marketSeed===s.marketSeed&&['initial','cash','invested','returned','expenses','dividends'].every(k=>a[k]===b[k])&&a.portfolio.length===count&&JSON.stringify(a.portfolio.map(({capital,...c})=>c))===JSON.stringify(s.portfolio.slice(0,count).map(({capital,...c})=>c))&&(!s.continuation||b.endingSeed===undefined||a.seed===b.endingSeed);
 }catch{return false;}
}
function saveEndingBackup(){
 const key=endingBackupKey(),raw=JSON.stringify(state);
 if(window.VCStore)return window.VCStore.read(key).then(existing=>{if(existing&&existing!==raw)throw Error('different ending');return window.VCStore.writeOnce(key,raw);});
 const existing=localStorage.getItem(key);
 if(existing&&existing!==raw)throw Error('different ending');
 if(!existing)localStorage.setItem(key,raw);if(localStorage.getItem(key)!==raw)throw Error('backup not saved');
}
function exportEndingBackup(){
 if(window.VCStore)return (async()=>{const key=endingBackupKey();for(const candidate of [key,KEY+'-2026-ending-'+state.marketSeed].filter(Boolean)){const raw=await window.VCStore.read(candidate);if(raw&&matchingEndingBackup(raw)){downloadJSON(raw,'远见资本-2026结局备份.json');return;}}toast('这台设备没有与本局匹配的结局备份，2026 年成绩摘要仍保存在当前存档中。');})();
 const key=endingBackupKey();for(const candidate of [key,KEY+'-2026-ending-'+state.marketSeed].filter(Boolean)){
  const raw=localStorage.getItem(candidate);if(raw&&matchingEndingBackup(raw)){downloadJSON(raw,'远见资本-2026结局备份.json');return;}
 }
 toast('这台设备没有与本局匹配的结局备份，2026 年成绩摘要仍保存在当前存档中。');
}
function endingDesk(exitIds=state.portfolio.filter(c=>c.exitReview?.year===state.year||c.liquidation?.year===state.year).map(c=>c.id)){
 modal(result().replaceAll('id="result-', 'id="ending-'));
 $('ending-details').onclick=()=>{if(!showExitNotice(exitIds))toast('本次没有持仓需要清算，历次投资记录已归档。');};$('ending-leaderboard').onclick=()=>leaderboardDesk();
}

function render(persist=true){if(persist)save();recordBoard();prepareCompanyArt();const s=state,e=VC.era(s.year),active=s.portfolio.filter(c=>c.status==='active'),assets=VC.nav(s),book=assets-s.cash;const options=[...new Set(s.deals.map(c=>c.sector))];let content='';if(tab==='deals'){const deals=s.deals.filter(c=>(filter==='all'||c.sector===filter)&&(stageFilter==='all'||c.capital?.stage===stageFilter)&&(kindFilter==='all'||kindFilter==='technology'&&c.capital?.technology||kindFilter==='strategic'&&VC.resourceQuote(state,c,VC.investmentTerms(c,state).minimum).ok)).sort((a,b)=>Number(!!VC.historicalProject(b))-Number(!!VC.historicalProject(a))); content=`<div class="section-intro"><span>${s.ended?'基金已结案，项目和回款都已归档':'今年送来 '+s.deals.length+' 份项目材料'+(s.extraDeals?'，其中 '+s.extraDeals+' 份由研究员带回':'')}</span><details class="project-filters" ${window.matchMedia?.('(max-width:700px), (max-width:1000px) and (max-height:500px)').matches&&filter==='all'&&stageFilter==='all'&&kindFilter==='all'?'':'open'}><summary>筛选项目${filter!=='all'||stageFilter!=='all'||kindFilter!=='all'?' · 已启用条件':' · 行业、轮次与属性'}</summary><div class="filter-controls"><select id="sector-filter" aria-label="筛选项目行业"><option value="all">全部行业</option>${options.map(x=>`<option ${filter===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="stage-filter" aria-label="筛选融资轮次"><option value="all">全部轮次</option>${Object.entries(VC.fundingStages).map(([key,p])=>`<option value="${key}" ${stageFilter===key?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="kind-filter" aria-label="筛选项目属性"><option value="all">全部项目</option><option value="technology" ${kindFilter==='technology'?'selected':''}>科创创业项目</option><option value="strategic" ${kindFilter==='strategic'?'selected':''}>可产业协同</option></select></div></details></div><div class="deal-grid">${deals.map(dealCard).join('')||`<div class="empty"><h3>${s.ended?'投资期已结束':s.deals.length?'当前筛选没有匹配项目':'今年桌上的案子都看完了'}</h3><p>${s.ended?'查看投资组合，复盘每一笔退出。':s.deals.length?'换个轮次、行业或项目属性看看，其他案卷仍在桌上。':'桌上的企业还在经营，等你安排完，今年就可以收尾了。'}</p></div>`}</div>`;}else if(tab==='portfolio'){content=`<div class="section-intro"><span>${active.length} 个持有项目 · ${s.portfolio.length-active.length} 个已退出项目</span><span>账面估值不等于退出回款</span></div>${active.slice().sort((a,b)=>(!!b.distress*3+!!b.exitOffer*2+!!b.round)-(!!a.distress*3+!!a.exitOffer*2+!!a.round)).map(portfolioCard).join('')}${s.portfolio.some(c=>c.status!=='active')?`<details class="archive"><summary>已退出项目 · ${s.portfolio.length-active.length} 笔</summary>${s.portfolio.filter(c=>c.status!=='active').map(portfolioCard).join('')}</details>`:''}${!s.portfolio.length?'<div class="empty"><h3>还没有投出第一笔钱。</h3><p>第一批材料已经送到项目池，研究和投资的钱都由基金出。</p></div>':''}`;}else if(tab==='market'){content=marketPage();}else if(tab==='team'){content=teamPage();}else{content=s.logs.map(l=>`<div class="history-row"><time>${l.year}</time><p>${esc(archiveText(l.text))}</p></div>`).join('');}
$('app').innerHTML=`<div class="desk-shell"><aside class="desk-rail"><div class="rail-heading"><img class="office-emblem" src="icon.svg" alt=""><span>投资事务所</span><small>EST. 1990</small></div><nav class="tabs" aria-label="基金工作台"><button data-tab="deals" aria-current="${tab==='deals'?'page':'false'}" class="${tab==='deals'?'active':''}">项目池<span class="count">${s.deals.length}</span></button><button data-tab="portfolio" aria-current="${tab==='portfolio'?'page':'false'}" class="${tab==='portfolio'?'active':''}">投资组合<span class="count">${active.length}</span></button><button data-tab="market" aria-current="${tab==='market'?'page':'false'}" class="${tab==='market'?'active':''}">行业竞争</button><button data-tab="team" aria-current="${tab==='team'?'page':'false'}" class="${tab==='team'?'active':''}">基金团队<span class="count">${s.ended?0:Object.values(s.team).filter(t=>t.active).length}</span></button><button data-tab="history" aria-current="${tab==='history'?'page':'false'}" class="${tab==='history'?'active':''}">投资日志</button></nav><div class="rail-seal">长线 · 耐心 · 判断<span>LONGVIEW CAPITAL</span></div></aside><div class="desk-main"><section class="intro office-scene"><div class="office-copy"><div class="eyebrow">远见资本 · 常青资本账户</div><h1>${s.ended?"远见资本 · 基金结案":s.year===1990?"第一年的投委会":s.year+" 年 · 投委会"}</h1><p>${s.ended?"持仓已经全部结清，每笔回款都能在档案里找到。":active.length?"持有 "+active.length+" 家企业。今年的报表和来信都在这里。":s.year===1990&&!s.portfolio.length?"1,000 万启动资金已到账，先看今年的项目。":"眼下没有持仓。今年的新项目材料已经送来，过往记录仍在档案里。"}</p></div><div><div class="year-controls"><div class="year-number">${s.year}<small>已经营 ${Math.min(60,s.year-1990)} / 60 年</small></div><button class="primary advance" id="advance" ${s.ended?'disabled':''}>${s.ended?'基金已结案':s.year===VC.endYear(s)-1?'进入 '+VC.endYear(s)+' · 清算':'进入下一年'} <span aria-hidden="true">→</span></button></div><div class="save-status" id="save-status" role="status" aria-live="polite">${saveStatus()}</div></div></section><section class="metrics" aria-label="基金关键指标"><div class="metric"><div class="metric-label">可用资金</div><div class="metric-value">${num(s.cash)}<small>万元</small></div><div class="metric-note">${s.ended?'基金清算后的现金余额':'可用于投资与后续跟投'}</div></div><div class="metric"><div class="metric-label">基金净资产 <span title="现金加持有股权的账面价值">ⓘ</span></div><div class="metric-value">${num(assets)}<small>万元</small></div><div class="metric-note">现金 + 股权账面价值</div></div><div class="metric"><div class="metric-label">已经收回的钱</div><div class="metric-value">${num(s.returned)}<small>万元</small></div><div class="metric-note">退出/减持 ${num(s.returned-s.dividends)} 万 · 分红 ${num(s.dividends)} 万</div></div><div class="metric"><div class="metric-label">基金回报</div><div class="metric-value ${assets>=s.initial?'positive':'negative'}">${assets>=s.initial?'+':''}${((assets/s.initial-1)*100).toFixed(1)}<small>%</small></div><div class="metric-note">${s.continuation?'自 1990 年成立以来的累计回报':s.ended?'最终净收益 / 初始资本':'含未实现收益，扣除基金支出'}</div></div></section><div class="desk-stage"><section class="desk-content" id="desk-content"><div class="dossier-heading"><span>${({deals:'项目案卷',portfolio:'持仓档案',market:'行业观察',team:'合伙团队',history:'往来纪事'})[tab]}</span><small>${s.year} / LONGVIEW JOURNAL</small></div>${!state.ruleset?'<div class="migration-note">旧档原有经营参数、资金和历史记录保留，投资期延续至 2050 年。</div>':''}${tab==='portfolio'||s.ended?result():''}${['deals','portfolio'].includes(tab)&&!s.ended?partnerLetter()+decisionAgenda():''}${['deals','portfolio'].includes(tab)&&VC.annualReview(state).length?`<details class="annual-dispatch"><summary>${s.year} 年度纪要 · ${VC.annualReview(state).length} 份企业消息</summary>${yearReview()}</details>`:''}${content}</section><aside class="sidebar"><section class="era"><div class="era-top">行业简报 <span>${s.year} / ${e.name}</span></div><h2>${e.headline}</h2><p>${e.text}</p><div class="era-bottom"><span>最近常见的案子</span>${e.hot.map(h=>`<b>${h}</b>`).join('')}</div></section><section class="side-card"><h2 class="side-title">账上的安排 </h2><div class="allocation"><span style="width:${assets?book/assets*100:0}%;background:#314d61"></span><span style="width:${assets?s.cash/assets*100:100}%;background:#c4d0d5"></span></div><div class="legend"><span><i class="dot"></i>持有股权</span><em>${num(book)} 万</em></div><div class="legend"><span><i class="dot" style="background:#c4d0d5"></i>现金储备</span><em>${num(s.cash)} 万</em></div><div class="hint">${s.ended?'基金已结清，投入、费用、分红和退出都已归档。':s.cash<100?'账上的钱不多了，后面的跟投和团队薪酬还等着安排。':'项目款投出去以后，跟投和团队还会用钱。企业需要补周转缺口时，也会再来找股东。'}${s.ended?'':'<br>年度运营：最多 10 万。'}<br>${s.ended?'基金已结束，不再续付薪酬。':'下期团队薪酬：'+num(VC.payroll(s))+' 万，年末自动续聘。'}</div></section><section class="side-card"><h2 class="side-title">基金净资产 <small>万元</small></h2><strong class="nav-current">${num(assets)}</strong>${chart()}<div class="chart-labels"><span>1990</span><span>${s.year===1990?'基金成立':s.year}</span></div></section><section class="side-card"><h2 class="side-title">最近的往来 </h2>${s.logs.slice(0,4).map(l=>`<div class="log-item"><time>${l.year}</time><p>${esc(archiveText(l.text))}</p></div>`).join('')}</section></aside></div></div></div>`;
if($('result-details'))$('result-details').onclick=()=>{if(!showExitNotice(state.portfolio.filter(c=>c.exitReview?.year===state.year||c.liquidation?.year===state.year).map(c=>c.id)))toast('本次没有持仓需要清算，历次投资记录已归档。');};if($('result-leaderboard'))$('result-leaderboard').onclick=()=>leaderboardDesk();if($('market-filter'))$('market-filter').onchange=e=>{marketFilter=e.target.value;render(false);};$('advance').onclick=advancePrompt;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render(false);$('desk-content').scrollIntoView({block:'start',behavior:'instant'});});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action,b.dataset.id));document.querySelectorAll('[data-team-action]').forEach(b=>b.onclick=()=>teamAction(b.dataset.role,b.dataset.teamAction));document.querySelectorAll('[data-strategy]').forEach(sel=>sel.onchange=()=>{VC.setStrategy(state,sel.dataset.strategy,sel.value);save();const c=state.portfolio.find(x=>x.id===sel.dataset.strategy),preview=sel.closest('.portfolio-row').querySelector('.strategy-preview');if(preview&&c)preview.outerHTML=strategyPreview(c);toast('就按这个安排经营，来年看结果。');});if($('stage-filter'))$('stage-filter').onchange=e=>{stageFilter=e.target.value;render(false);};if($('kind-filter'))$('kind-filter').onchange=e=>{kindFilter=e.target.value;render(false);};if($('sector-filter'))$('sector-filter').onchange=e=>{filter=e.target.value;render(false);};prepareProjectImages();updateSaveStatus();}
function detail(id,thesis='cash',mode='financial'){const c=state.deals.find(c=>c.id===id);if(!c)return;const terms=VC.investmentTerms(c,state),l=VC.level(state,'diligence'),fee=VC.diligenceCost(state),canResearch=c.ddLevel<l,precision=[.18,.12,.07,.03][Math.max(0,c.ddLevel)];modal(`${companyPicture(c,'dossier')}<div class="eyebrow">项目材料</div><h2>${esc(companyName(c))}</h2>${projectTag(c)}<p>${esc(c.sector)} · ${projectStage(c)} · ${esc(VC.companyIdentity(c).story)}</p>${historicalNote(c)}${capitalOfferPanel(c)}<div class="numbers"><div><label>投前估值 / 万</label><strong>${num(c.value)}</strong></div><div><label>企业人数</label><strong>${c.team}</strong></div><div><label>周转情况</label><strong>${c.cashFlow>0?'经营有结余':c.cashFlow===0?'收支平衡':c.runway+' 个月'}</strong></div></div>${financeSummary(c)}<div class="dd-box">${c.dd?`<b>${['初步尽调','补充尽调','深入尽调','全面尽调'][Math.max(0,c.ddLevel)]} · ${c.quality>.72?'经营底子较好':c.quality>.48?'有长处，也有短板':'经营短板明显'}</b>经营能力判断：${Math.max(0,Math.floor((c.quality-precision)*100))}—${Math.min(100,Math.ceil((c.quality+precision)*100))} / 100<br>生意波动：${c.volatility>.6?'较高':'中等'}<br>主要风险：${esc(companyRisk(c))}。${c.ddLevel>=2?`<br>若收入少 20%，仍按眼下人员和费用结构，经营利润约 ${num(VC.stressProfit(c))} 万元（暂不另改人员和竞争条件）。`:''}${c.ddLevel>=3?`<br>现金还够多久：${c.cashFlow<0?'当前现金消耗下可维持约 '+c.runway+' 个月，新增投资会延长储备。':'眼下经营能留下现金，后续扩张还得另算开支。'}`:''}`:'<b>这些材料由创始人提供，还没有独立核查。</b>请人查一遍，才能对团队和经营能力多些把握。'}${canResearch?`<br><button id="research" ${state.cash<fee?'disabled':''}>${fee===0?(c.dd?'免费补全报告':'免费尽调'):'安排基础尽调 · '+fee+' 万元'}</button><p class="modal-note">${fee===0?'由在岗专家办理，已含本期薪酬，不另扣项目费用。':'尚无在岗尽调专家，本次基础尽调按项目收费。'}</p>`:c.dd?'<p class="modal-note">当前等级的尽调报告已齐全，无需重复办理。</p>':''}</div>${diligenceEconomics(c)}${ventureRiskPanel(c)}<h4>你看好它哪一点</h4><label class="thesis-label">投资理由<select id="investment-thesis" aria-label="投资理由"><option value="cash">经营能持续产生现金</option><option value="growth">客户和收入还能继续增长</option><option value="product">产品改进能形成竞争力</option></select></label><h4>这次以什么方式投资</h4><label class="thesis-label">投资方式<select id="investment-mode" aria-label="投资方式"><option value="financial">财务投资 · 资金入股</option><option value="strategic">产业协同 · 资金＋资源</option></select></label>${mode==='strategic'?'<p class="round-note">'+esc(VC.resourceQuote(state,c,terms.minimum).ok?'需由基金另付协调费；认购核对页会列出资源来源与费用。':VC.resourceQuote(state,c,terms.minimum).reason)+'</p>':''}<h4>这次准备投多少</h4><p class="modal-note">认购档位随融资阶段、整轮规模和基金资产调整。大额认购须留足已知跟投与下期运营储备。产业协同另付协调费用，不能把承诺的资源当作已到账的资金或订单。</p>${c.capital?'<p class="modal-note">'+(terms.largeLimit>200?'本项目超过 200 万的单笔认购上限为 '+num(terms.largeLimit)+' 万，阶段自带的大额档也适用。':'当前基金规模仅适合 200 万以内的认购；本轮若有更高起投要求，可先查看其他项目。')+'</p>':''}<div class="ticket-options">${terms.amounts.map(a=>`<button class="ticket" data-amount="${a}" title="${esc(VC.investmentOutlook(state,c.id,a,mode)?.reason||'')}" ${!VC.investmentOutlook(state,c.id,a,mode)?.ok?'disabled':''}>${a.toLocaleString('zh-CN')} 万<small>持股 ${pct(VC.investmentOutlook(state,c.id,a,mode)?.equity||0)}</small>${state.ruleset===12?'<small>基金剩余 '+num(VC.investmentOutlook(state,c.id,a,mode)?.cashAfter??state.cash-a)+' 万</small>':''}${terms.scaled&&a>200?'<small>'+(!VC.investmentOutlook(state,c.id,a,mode)?.ok?(state.cash<a?'现金不足':'认购条件未满足'):'核对后认购')+'</small>':''}</button>`).join('')}</div><p class="modal-note">基金账上还有 ${num(state.cash)} 万。${state.ruleset===12?'已经报来的跟投，加上下期运营和团队，合计要留 '+num(VC.investmentOutlook(state,c.id,terms.minimum,mode).reserve)+' 万；这还没有为未来新项目留钱。':''}投资款进入公司账上，后续由企业安排经营和项目建设。</p><details class="detail-finance"><summary>查看成本与财务记录</summary>${financeDetails(c)}</details>`);if($('research'))$('research').onclick=()=>{const choice=$('investment-thesis').value,way=$('investment-mode').value;if(VC.research(state,id)){render();detail(id,choice,way);toast('尽调报告已更新。');}};$('investment-thesis').value=thesis;$('investment-mode').value=mode;$('investment-mode').onchange=e=>detail(id,$('investment-thesis').value,e.target.value);document.querySelectorAll('.ticket').forEach(b=>b.onclick=()=>{const amount=Number(b.dataset.amount),choice=$('investment-thesis').value;if(c.capital){capitalInvestmentConfirm(id,amount,choice,$('investment-mode').value);return;}if(VC.investmentOutlook(state,id,amount)?.large){investmentConfirm(id,amount,choice);return;}if(VC.invest(state,id,amount,choice)){close();render();toast('款已经打到公司，股权也记下了。');}else{detail(id,choice);toast('这笔投资的现金或融资条件已变化，请重新核对。');}});}
function investmentConfirm(id,amount,thesis){
 const c=state.deals.find(c=>c.id===id),q=VC.investmentOutlook(state,id,amount);if(!c||!q){if(c)detail(id,thesis);toast('融资条件已变化，请重新选择金额。');return;}
 modal(`<div class="eyebrow">认购核对</div><h2>向 ${esc(companyName(c))} 投资 ${num(amount)} 万</h2>${projectTag(c)}<div class="numbers"><div><label>投后持股</label><strong>${pct(q.equity)}</strong></div><div><label>占基金净资产</label><strong>${pct(q.fundShare)}</strong></div><div><label>占可用现金</label><strong>${pct(q.cashShare)}</strong></div></div><p>投前估值 ${num(c.value)} 万，投后估值 ${num(c.value+amount)} 万。款项进入企业账上，经营、分红和退出仍按原有规则结算。</p><p>认购后基金剩余现金 <b>${num(q.cashAfter)} 万</b>；已知跟投与下期运营储备合计 <b>${num(q.reserve)} 万</b>，扣除后还有 ${num(q.cashAfter-q.reserve)} 万。未来的新项目与追加融资仍需另作安排。</p><p class="modal-note">投资额增加会同时放大可能的收益和损失。估值与持股比例不代表回款承诺。</p>${q.reason?'<p class="round-note">'+esc(q.reason)+'</p>':''}<div class="modal-actions"><button id="investment-back">返回项目材料</button><button class="primary" id="investment-confirm" ${q.ok?'':'disabled'}>确认认购 ${num(amount)} 万</button></div>`);
 $('investment-back').onclick=()=>detail(id,thesis);
 $('investment-confirm').onclick=()=>{const button=$('investment-confirm');button.disabled=true;if(VC.invest(state,id,amount,thesis)){close();render();toast('认购已完成，资金与股权已经入账。');}else{investmentConfirm(id,amount,thesis);toast('现金或融资条件已变化，请重新核对。');}};
}

function act(action,id){const c=state.portfolio.find(c=>c.id===id);if(action==='detail')return detail(id);if(!c)return;if(action==='capital'||action==='sell'&&c.capital?.public)return capitalDesk(id);if(action==='board')return boardDesk(id);if(action==='offer')return offerDesk(id);if(action==='dividend')return dividendDesk(id);if(action==='rebuild')return rebuildDesk(id);if(action==='divest')return divestDesk(id);if(action==='liquidation')return liquidationDesk(id);if(action==='workout')return workoutDesk(id);if(action==='acquisition')return acquisitionDesk(id);if(action==='record'){modal(`${companyPicture(c,'dossier')}<div class="eyebrow">企业档案</div><h2>${esc(companyName(c))}</h2>${projectTag(c)}<p>${esc(VC.companyIdentity(c).story)}</p>${historicalNote(c)}${c.status!=='active'?exitRecap(c):''}${economicsNote(c)}${strategyPreview(c)}${financeDetails(c)}<details><summary>经营与投资事件</summary><ul>${c.notes.map(n=>`<li>${esc(archiveText(n))}</li>`).join('')}</ul></details>`);}if(action==='follow'){const q=VC.followQuote(state,id);modal(`<h2>继续投入 ${esc(companyName(c))}？</h2>${projectTag(c)}<p>本轮认购需要 ${num(q.cost||0)} 万，基金将剩余 ${num(state.cash-(q.cost||0))} 万。新增持股 ${pct(q.delta||0)}，办理后持股 ${pct(q.after||c.equity)}。已卖出的股份不会恢复。</p><p>企业今年净现金流 ${signed(c.cashFlow)} 万。本轮筹款用于${esc(archiveText(c.round?.purpose||'补充经营资金'))}。企业融资此前已到账，本次不重复注资；订单仍需企业争取。</p>${q.reason?'<p class="round-note">'+esc(q.reason)+'</p>':''}<div class="modal-actions"><button id="cancel-follow">暂不跟投</button><button id="confirm-follow" class="primary" ${q.ok?'':'disabled'}>确认跟投</button></div>`);$('cancel-follow').onclick=close;$('confirm-follow').onclick=()=>{if(VC.follow(state,id)){close();render();toast('本轮认购已完成，现金与新增股份已入账。');}};}if(action==='sell'){modal(`<div class="eyebrow">股权转让</div><h2>转让 ${esc(companyName(c))} 的全部股权？</h2>${projectTag(c)}<p>账面价值 ${num(c.value*c.equity)} 万。${state.ruleset===12?'经营业务按':'按'} ${Math.round(VC.saleFactor(state)*100)}% 折价转让${state.ruleset===12?'，账上现金按原额扣除债务后分配':''}，预计到账 <b>${num(VC.exitValue(c,VC.saleFactor(state)))} 万元</b>。成交后，你不再分享这家企业的未来收益。</p><div class="modal-actions"><button id="cancel">继续持有</button><button class="primary" id="confirm-sell">确认转让</button></div>`);$('cancel').onclick=close;$('confirm-sell').onclick=()=>{if(VC.sell(state,id)){close();render();showExitNotice([id]);}};}}
function advancePrompt(){const troubled=state.portfolio.filter(c=>c.status==='active'&&c.distress);const pending=state.portfolio.filter(c=>c.status==='active'&&c.round).length;modal(`<div class="eyebrow">年度投委会</div><h2>${state.year===VC.endYear(state)-1?'进入 '+VC.endYear(state)+' 年结算？':'结束 '+state.year+' 年的投资决策？'}</h2><p>${state.portfolio.some(c=>c.exitOffer)?'今年的退出报价到此作废，明年得重新等买方。':''}桌上剩下的 ${state.deals.length} 份项目材料会收走${pending?'，'+pending+' 个跟投机会将到期':''}。手里的企业继续经营，来年的账和消息会一起送来。</p>${troubled.length?`<div class="round-note">以下企业尚未完成救助，确认推进将立即清算：${troubled.map(c=>esc(companyRef(c))).join('、')}。可回到投资组合评估业务出售；继续推进将自动拍卖资产，先偿债、再按股比分配余款。</div>`:''}<p style="margin-top:12px">${state.year===VC.endYear(state)-1?VC.endYear(state)+' 年完成最后一个经营年度后，上市持仓参考市价处置；未上市'+(state.ruleset===12?'经营业务按估值的 '+Math.round(VC.terminalFactor(state)*100)+'% 强制处置，企业现金按原额扣除债务后分给股东':'剩余股权按账面价值的 '+Math.round(VC.terminalFactor(state)*100)+'% 变现')+'；不再续付团队薪酬。':'今年团队的薪酬已经付过。年末另付最多 10 万运营费，再续上下一年的团队薪酬 '+num(VC.payroll(state))+' 万；钱不够的岗位会暂时停工。'}</p><div class="modal-actions"><button id="cancel">继续决策</button><button class="primary" id="confirm-advance">${state.year===VC.endYear(state)-1?'完成清算':'确认进入 '+(state.year+1)+' 年'}</button></div>`);$('cancel').onclick=close;$('confirm-advance').onclick=()=>{const activeIds=new Set(state.portfolio.filter(c=>c.status==='active').map(c=>c.id));for(const c of state.portfolio.filter(c=>c.status==='active'))c.exitPolicy='review';VC.advance(state);filter='all';stageFilter='all';kindFilter='all';if(state.ended)tab='portfolio';close();render();const exits=state.portfolio.filter(c=>activeIds.has(c.id)&&c.status!=='active').map(c=>c.id),offers=state.portfolio.filter(c=>VC.exitQuote(state,c.id)).map(c=>c.id);if(state.ended){acknowledgeExitNotice();endingDesk(exits);}else if(!showExitNotice(exits,offers))toast('已进入 '+state.year+' 年，企业经营结果已更新。');window.scrollTo({top:0,behavior:'smooth'});};}
$('guide').onclick=()=>modal(`<div class="eyebrow">合伙人备忘</div><h2>基金的约定</h2><h4>资金与期限</h4><p>1990 年，远见资本以 1,000 万元长期资本开始运作，回款可循环投入。每年有 4 份常规项目材料，研究员还能额外带回 1 / 2 / 3 份。部分年份另有专项融资机会，不占常规名额。当年没投的案子，来年不再放在桌上。从 1990 年连续经营至 2050 年，共 60 年；2050 年是本段游戏的统一结算点。中途不因年份而强制清仓；企业、现金、股份和团队持续接续，2050 年统一完成结算。</p><p>尽调、团队和日常运营都从基金账上付。每年运营最多 10 万，团队年末续付下一年薪酬；钱不够的岗位暂停。企业账上的钱归企业，分红和退出后才回到基金。</p><h4>项目规模</h4><p>中后期的常规项目会逐步增加成长与规模企业，同时保留早期小项目。大企业的收入、团队、成本和所需资金一起增加，报价仍按经营与市场条件形成。行业客户来自现有市场，规模和名气都不代表经营质量。</p><h4>普通项目认购</h4><p>认购起点随轮次和企业估值变化，早期天使项目可从 20 万起，成长及上市前项目通常需要更高金额。随着基金规模扩大，大额档按基金净资产的 20% 与项目投前估值的 50% 取较低值，并以本轮募集总额为上限；单笔超过 200 万时，阶段自带金额也受上述上限约束；大额单笔投后持股不超过三分之一。大额认购需先核对，并留足已经报来的跟投与下一年的运营、团队薪酬。旧规则基金沿用原档位，专项融资采用项目材料列示的金额。</p><h4>融资轮次与投资方式</h4><p>天使和 Pre-A 侧重产品与客户验证，A 轮关注可复制的业务，B、C 轮及以后支持扩张与整合，Pre-IPO 用于发行准备。轮次可能跳过、延期或按较低估值融资；过桥融资用于补足当期缺口，不自动代表企业升级。科创创业是项目属性，产业资源赋能是投资方式，两者都可以出现在多个轮次。</p><p>IPO 是公开发行新股：募集款进入公司，原股东按新增股份稀释。上市前持仓按发行条款锁定 1—3 年，普通 IPO 新股认购可在上市当年按市场情况减持，战略配售按条款锁定。Pre-IPO 不保证上市，上市也不保证盈利。</p><h4>专项融资</h4><p>部分年份会出现额外的融资机会。认购期限、起投金额与本轮持股上限都列在项目材料中，资金和人员安排仍要从基金与企业各自的账上支付。当年没有认购，融资窗口就会关闭。</p><h4>名气与经营</h4><p>估值、回款账期、持续获客费用和可用现金，都会影响投资结果。尽调能提供经营依据，企业仍需自己争取订单、控制成本并安排融资。危机引起的费用和回款缺口，会记入企业年报。</p><h4>材料、判断和年报</h4><p>创始人报的收入和估值，只是第一份材料。独立尽调会补上团队能力、经营短板与压力测算。好公司也可能要价太高，研究报告也不知道下一年会发生什么。每次出手可留下投资理由，结案时再回看。</p><p>没有在岗专家时，基础尽调每个项目 5 万。尽调专家在岗期间，项目尽调和报告补全已含薪酬；入职、晋升或恢复合作时，已尽调报告自动补全。暂停合作后，未尽调项目恢复基础收费。历史已付费用照原账保留。</p><h4>企业怎么用钱</h4><p>扩张先花钱，订单未必马上跟来。产品、设备和渠道项目由公司出预算，分两阶段推进，可能延期和超支；第三年还没做完就停，已花的钱不退。2049 年起不再启动来不及完成的新建设项目。分红要在连续两个完整年度利润和现金流都转正后再议，还得先补亏损、留够周转和还债的钱。</p><h4>缺钱时怎么谈</h4><p>企业会按周转缺口或已验证的扩张计划融资；进入下一轮需要经营里程碑，并非每年自动升级。引入新股东会稀释持股。当年按比例跟投能保住原比例，但基金也得再掏钱。并购可以用企业自有钱、贷款或外部增资；贷款要还本付息，新股东以后也要分收益。</p><p>到期款付不出时，今年还能谈展期、债转股或由基金救助。展期和转股都不会带来现金，缺口留到来年就得清算。清算先付费用、还债，余下的才归股东。</p><h4>什么时候收回投资</h4><p>未上市持仓满两年可以主动谈转让，满四年可能收到并购报价。买方只等当年答复，下次不一定出同样的价；整合和建设没结束时，先不办退出。上市须另行准备和发行，之后按锁定条款及市场承接能力减持，上市本身不把退出款付给基金。</p><p>${state.ruleset===12?'这只基金采用新规则：报价中的溢价和折价只算在经营业务上，现金按原额扣债后分给股东。主动转让经营业务从 50% 起，退出顾问每级多谈回 5 个百分点；到期强制处置从 45% 起，每级多 2.5 个百分点。':'这份旧档案沿用原规则：主动转让从账面股权的 65% 起，退出顾问每级多谈回 5 个百分点；到期处置从 70% 起，每级多 2 个百分点。'}等到最后一年，未必比现在卖得好；早卖掉，也就不再分享后面的经营。</p><h4>把档案留好</h4>${state.campaign?.backupKey?'<div class="modal-actions"><button id="previous-campaign-export">导出接续前原始存档</button></div>':''}<p>进度存在这台设备上。导出一份档案，可留作备份或换设备接着玩；导入和新开基金都会替换当前进度。旧档接续前会留备份，历史资金与股份照原账保留。</p><details><summary>旧档备份</summary>${state.continuation?'<button id="ending-backup-export">导出旧版结案备份</button>':''}<div class="modal-actions">${[9,8,7,6,5,4,3,2,1].map(v=>`<button id="${v===1?'legacy':'v'+v}-export">导出 v0.${v} 备份</button>`).join('')}</div></details><p class="modal-note">企业背景与经营记录可在项目档案中查阅。2027—2050 年采用未来情景推演。客户数按统一口径折算，金额单位为万元；税收、通胀、真实司法程序和基金分成不另计算。<a class="source-link" href="https://www.federalreserve.gov/newsevents/speech/bernanke20100103a.htm" target="_blank" rel="noopener">年代背景资料</a></p><div class="modal-actions"><button id="guide-export">导出当前存档</button></div>`);
$('modal-content').addEventListener('click',e=>{if(e.target.id==='guide-export')exportSave();if(e.target.id==='previous-campaign-export')exportPreviousCampaign();if(e.target.id==='ending-backup-export'){try{const exported=exportEndingBackup();if(exported&&typeof exported.catch==='function')exported.catch(()=>toast('结局备份暂时无法读取，当前存档仍在。'));}catch{toast('结局备份暂时无法读取，当前存档仍在。');}}if(['legacy-export','v2-export','v3-export','v4-export','v5-export','v6-export','v7-export','v8-export','v9-export'].includes(e.target.id)){try{const version=e.target.id==='v9-export'?9:e.target.id==='v8-export'?8:e.target.id==='v7-export'?7:e.target.id==='v6-export'?6:e.target.id==='v5-export'?5:e.target.id==='v4-export'?4:e.target.id==='v3-export'?3:e.target.id==='v2-export'?2:1;const key=KEY+'-v'+version+'-backup',exportRaw=raw=>{if(!raw)return toast('这台设备上没有找到那份旧档案。');downloadJSON(raw,'远见资本-升级前备份.json');};if(window.VCStore)window.VCStore.read(key).then(exportRaw,()=>toast('备份暂时读不出来。'));else exportRaw(localStorage.getItem(key));}catch{toast('备份暂时读不出来。');}}});
function downloadJSON(raw,name){const blob=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('存档已导出。');}
function exportSave(){if(saveLoadError){try{const raw=progressStorage.getItem(KEY);if(raw){downloadJSON(raw,'远见资本-原始存档.json');return;}}catch{}displayToast('原档暂时无法读取，请关闭其他游戏标签页后刷新重试。');return;}downloadJSON(JSON.stringify(state,null,2),'远见资本-'+state.year+'.json');}
$('export').onclick=exportSave;$('import').onclick=()=>{$('file').value='';$('file').click();};$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>32*1024*1024)throw Error();const original=await f.text(),parsed=JSON.parse(original),candidate=VC.isContinuous(parsed)?VC.migrate(parsed):VC.toContinuous(parsed,original);modal(`<h2>载入 ${candidate.year} 年的基金存档？</h2><p>可用资金 ${num(candidate.cash)} 万元，累计投资 ${candidate.portfolio.length} 家企业。载入将替换当前本机进度。</p><div class="modal-actions"><button id="cancel">取消</button><button class="primary" id="confirm-import">载入存档</button></div>`);$('cancel').onclick=close;$('confirm-import').onclick=()=>{const button=$('confirm-import');button.disabled=true;lockReplacement(true);const failed=()=>{button.disabled=false;lockReplacement(false);displayToast('无法备份旧档，当前进度已保留。');};const load=()=>replaceProgress(candidate,()=>{acknowledgeExitNotice();tab='portfolio';filter='all';stageFilter='all';kindFilter='all';close();render(false);toast('存档已载入并保存。');},button);const keep=()=>VC.isContinuous(parsed)?load():afterWrite(preserveCampaignOriginal(original),load,failed);try{return parsed.version<10?afterWrite(backupLegacy(original,parsed.version),keep,failed):keep();}catch{return failed();}};}catch{toast('无法载入：这份档案里的账对不上，当前进度还在。');}};
$('reset').onclick=()=>{modal('<div class="eyebrow">另立一只基金</div><h2>从 1990 年重新出发？</h2><p>新基金将拥有 1,000 万元启动资金，项目和后续经历都会重新开始。新基金按新的经营规则运行，扩张开支、买入价格和退出时机都得重新盘算。当前进度将被替换，请先导出存档。</p><div class="modal-actions"><button id="backup">导出当前存档</button><button id="cancel">取消</button><button class="primary" id="confirm-reset">创建新基金</button></div>');$('backup').onclick=exportSave;$('cancel').onclick=close;$('confirm-reset').onclick=()=>{replaceProgress(VC.createCampaign(),()=>{acknowledgeExitNotice();tab='deals';filter='all';stageFilter='all';kindFilter='all';close();render(false);toast('新基金已成立并保存。');},$('confirm-reset'));};};render(initialSaveNeeded);restoreExitNotice();
